programs.sol:
"""Approximate a definition/predication boundary signal.

Predict negative spikes at copulas following abstract subjects (especially
an aim, problem, or idea), usually weak after pronouns or math symbols.
Word classes, noun suffixes, and case give coarse subject types. Recent
'what ...' and 'one/another ...' phrases strengthen the response; plurals
weaken it. Also cover modal + be, clause-introducing 'that', labels followed
by colons, and several non-English counterparts. Everything else is zero.
The 80-character memory resets at document boundaries. This deliberately
omits fine-grained lexical and longer-context variation.
"""
import re

READS = ()
GOALS = set('goal aim purpose objective intention mission need idea thing do'.split())
ISSUES = set(
    'problem question issue solution answer reason mistake challenge '
    'alternative possibility choice option trick '
    .split()
)
DISCOURSE = set(
    'approach way task result difference key point fact claim condition '
    'hypothesis assumption conclusion explanation reality story case step '
    .split()
)
TECHNICAL = set(
    'method process model system function equation sum term product invention '
    'output input definition information name work study analysis sample '
    'project procedure design response test '
    .split()
)
HUMAN = set(
    'man woman boy girl father mother brother sister son daughter person '
    'people child children patient patients student students member members '
    'worker workers '
    .split()
)
PRONOUNS = set('i he she we you they who these those'.split())
CONNECTORS = set('and or but as than which that'.split())
NOMINAL_ENDINGS = ('tion', 'sion', 'ment', 'ness', 'ity', 'ance', 'ence', 'ship', 'ism')

# The typical response to singular present-tense copulas, by subject type.
SUBJECT_SCORE = {
    'goal': -3.27,
    'issue': -2.27,
    'discourse': -1.85,
    'technical': -1.18,
    'nominal': -0.97,
    'human': -0.58,
    'pronoun': 0.21,
    'it': 0.04,
    'this': -0.19,
    'what': -0.17,
    'there': -0.08,
    'here': -1.16,
    'connector': 0.03,
    'number': -0.36,
    'symbol': -0.1,
    'punctuation': -0.36,
    'proper': -0.39,
    'fragment': -0.5,
    'noun': -0.88,
    'space': -0.38,
}

def subject_kind(previous, tail):
    match = re.search(r'[A-Za-z]+$', tail)
    word = match.group() if match else ''
    lower = word.lower()
    singular = lower
    classes = GOALS | ISSUES | DISCOURSE | TECHNICAL
    if lower not in classes and lower.endswith('s'):
        singular = lower[:-1]
    if singular in GOALS:
        return 'goal'
    if singular in ISSUES:
        return 'issue'
    if singular in DISCOURSE:
        return 'discourse'
    if singular in TECHNICAL:
        return 'technical'
    if lower in HUMAN:
        return 'human'
    if lower in PRONOUNS:
        return 'pronoun'
    if lower in ('it', 'this'):
        return lower if word.islower() else 'pronoun'
    if lower in ('what', 'there', 'here'):
        return lower
    if lower in CONNECTORS:
        return 'connector'
    if singular.endswith(NOMINAL_ENDINGS):
        return 'nominal'
    p = previous.strip()
    if p.isdigit():
        return 'number'
    if p and (p[-1] in ')]}$' or (word and len(word) == 1)
              or (word and word.isupper())):
        return 'symbol'
    if not p:
        return 'space'
    if not word:
        return 'punctuation'
    if word[0].isupper():
        return 'proper'
    if not previous[0].isspace():
        return 'fragment'
    return 'noun'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token in (' is', ' was', ' are', ' were'):
        column = (' is', ' was', ' are', ' were').index(token)
        kind = subject_kind(previous, tail)
        value = SUBJECT_SCORE[kind]
        if column == 1:
            value *= 0.95
            if kind == "it":
                value = -0.12
        elif column == 2:
            value *= 0.5
        elif column == 3:
            value = 0.45 * value + 0.1
        if kind == "pronoun":
            value = (0.21, 0.21, 0.14, 0.27)[column]
        clause = re.split(r'[.!?;:\n,]', tail)[-1].lower()
        words = re.findall(r'[a-z]+', clause)
        strength = 1.0 if column < 2 else 0.5
        if len(words) > 2 and 'what' in words[:-2]:
            value -= 0.7 * strength
        if 'one' in words or 'another' in words:
            value -= 0.6 * strength
        if kind in ('noun', 'nominal', 'technical', 'here'):
            if any(w in words for w in ('main', 'primary', 'key', 'important',
                                         'best', 'first', 'next', 'only')):
                value -= 0.25 * strength
        if not tail:
            value = (-0.75, -0.85, 0.014, 0.1)[column]
    elif token == ' that':
        if previous in (' is', ' was', ' fact'):
            value = -0.51
        elif previous in (' are', ' be'):
            value = -0.27
    elif token == ' whether':
        value = -0.11 if previous != ' is' else -0.36
    elif token == ' be':
        modal = previous.strip().lower()
        value = {'would': -0.92, 'should': -0.80, 'must': -0.60,
                 'will': -0.32, 'could': -0.45,
                 'shall': -0.24}.get(modal, 0.12)
        if not tail:
            value = 0.27
    elif token == ' been':
        value = -0.04 if previous.strip() in ('has', 'have') else 0.18
    elif token == ' being':
        value = -0.13
    elif token in (':', '：'):
        kind = subject_kind(previous, tail)
        label = previous.strip().lower()
        if kind in ('goal', 'issue', 'discourse') or label in (
                'is', 'are', 'was', 'be', 'follows', 'expected', 'posts', 'joined',
                'term', 'equation', 'expression', 'inequality', 'area', 'volume'):
            value = -0.5
        else:
            value = -0.04
    elif token == '是':
        value = -0.65
        if tail.endswith(('目标', '目標', '目的', '理想', '重点', '重點',
                          '核心', '任务', '任務')):
            value = -2.7
        elif tail.endswith(('问题', '問題', '原因', '方法', '方式', '情况',
                            '情況', '特点', '特點', '特色', '概念', '功用')):
            value = -1.9
    elif token == '就是':
        value = -1.84
        if tail.endswith(('方式', '任务', '任務', '特色', '缺点', '缺點',
                          '工作', '目的', '目标', '目標')):
            value = -3.0
    elif token.endswith('的是'):
        value = -1.91
        if tail.endswith(('重要', '主要', '关键', '關鍵')):
            value = -3.3
    elif token == '的就是':
        value = -3.17
    elif token in ('主要是', '应该是', '目的是', '问题是', '原因是', '特点是'):
        value = -1.6
    elif token in ('在于', '在於'):
        value = -3.0
    elif token in (' является', 'のは'):
        value = -1.2
    elif token in (' là', ' es', ' é'):
        value = -0.08
    return (doc, token, (tail + token)[-80:]), float(value)

programs.haiku:
"""Adverbs of completeness and degree, as layers.0.mlp.down_proj:835 sees them.

The component writes a strongly negative value on a word that completes or
intensifies the verb or adjective after it: "is completely wrong", "were fully
understood", "highly", "really", "carefully". It writes a mildly positive value
on "views" and "opinion", and a small positive one on "very". Most other tokens
are near zero.

The program reads only the newest token and predicts
the activation from its class:
  - completely, entirely (and 完全, 全く): -6.0, the strongest
  - totally, wholly, altogether (and their translations): -4.8
  - fully, purely, thoroughly, utterly, ganz, 全, 毫无: -3.0
  - strong degree adverbs (highly, perfectly, largely, deeply, solely): -2.0
  - weaker degree and manner adverbs (really, quite, significantly): -1.1
  - other -ly adverbs: -1.0; word pieces that finish an -ly adverb (ally, ously): -0.8
  - sentence-linking and hedging adverbs (finally, actually, usually): -0.2
  - -ly words that are not adverbs (family, daily, only, early): 0
  - views, opinion: +2.0; very: +0.25
"""

READS = ()

COMPLETE = {"completely", "entirely", "完全", "全く"}
TOTAL = {"totally", "wholly", "altogether", "völlig", "совершенно", "completamente",
         "totalmente", "zupełnie", "전혀"}
FULLY = {"fully", "purely", "thoroughly", "utterly", "ganz", "toàn", "全", "毫无", "根本",
         "überhaupt", "вообще"}
STRONG = {"highly", "perfectly", "absolutely", "truly", "largely", "deeply", "solely",
          "partially", "mostly", "profoundly", "fundamentally", "distinctly", "вполне",
          "heavily", "strongly"}
DEGREE = {"really", "quite", "significantly", "substantially", "considerably", "essentially",
          "pure", "純", "纯", "全部", "全身", "greatly", "extremely", "incredibly", "partly",
          "squarely", "本当に"}
LINKING = {"actually", "approximately", "currently", "likely", "especially", "probably",
           "usually", "simply", "finally", "alternatively", "particularly", "typically",
           "nearly", "respectively", "early", "similarly", "consequently", "additionally",
           "specifically"}
NOT_ADVERB = {"family", "daily", "friendly", "apply", "supply", "multiply", "assembly", "july",
              "poly", "rely", "reply", "ally", "belly", "butterfly", "kimberly", "italy", "only",
              "just", "weekly", "monthly"}
FRAGMENTS = {"ly", "ally", "ably", "ically", "ously", "ently", "ely", "ensively", "ially",
             "ily", "efully"}


def step(carry, prefix, upstream):
    w = prefix.token_strings[-1].strip()
    lw = w.lower()
    if lw in COMPLETE or lw.endswith("pletely"):
        return carry, -6.0
    if lw in TOTAL:
        return carry, -4.8
    if lw in FULLY:
        return carry, -3.0
    if lw in STRONG:
        return carry, -2.0
    if lw in DEGREE:
        return carry, -1.1
    if lw in LINKING:
        return carry, -0.2
    if lw in {"views", "opinion", "opinions"}:
        return carry, 2.0
    if w == "very":
        return carry, 0.25
    if lw in NOT_ADVERB:
        return carry, 0.0
    if lw in FRAGMENTS:
        return carry, -0.8
    if lw.endswith("ly") and lw.isalpha() and len(lw) > 3:
        return carry, -1.0
    return carry, 0.0

programs.sol:
"""Approximate an orthographic i-onset signal.

Unspaced alphabetic pieces starting with normalized i/ı/и/і usually get
larger values before the word's first vowel. Length and English suffix
class set the amplitude; a previous i lowers it, while a single-vowel
prefix gets a bonus. A weaker y-onset rule and an 'et al' citation rule
cover additional responses. These are training-derived group averages,
not a reconstruction of token-specific variation.
"""
import unicodedata

READS = ()
VOWELS = set('aeiouyıаеёиоуыэюяіїє')
I_LETTERS = set('iıиі')
SUFFIXES = {
    'ing', 'ings', 'ion', 'ions', 'ity', 'ities', 'ies', 'ied',
    'ier', 'iest', 'ily', 'ic', 'ics', 'ical', 'ically', 'ious',
    'ist', 'ists', 'ize', 'ized', 'izing', 'isation', 'ization',
    'ised', 'ising', 'ine', 'ines', 'ite', 'ites', 'ian', 'ians',
    'ive', 'ives', 'ible', 'ibly', 'ient', 'ients', 'ience', 'iences',
}
# Columns: one letter, two letters, 3-4, 5-7, and 8+ letters.
RESPONSES = (
    (-0.05, 0.02, 0.06, 0.00, 0.03),  # no word prefix
    (0.25, 0.48, 0.60, 0.34, 0.17),   # prefix has no vowel
    (0.07, 0.08, 0.20, 0.18, 0.08),   # one vowel in prefix
    (0.02, 0.02, 0.11, 0.12, 0.01),   # several vowels in prefix
)


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if token.isalpha() and plain(token[0]) in I_LETTERS:
        # The u in a qu opening is not counted as a separate vowel.
        opening = plain(word).replace('qu', 'q')
        vowel_count = sum(c in VOWELS for c in opening)
        group = (0 if not word else 1 if vowel_count == 0
                 else 2 if vowel_count == 1 else 3)
        n = len(token)
        size = (0 if n == 1 else 1 if n == 2 else 2 if n <= 4
                else 3 if n <= 7 else 4)
        value = RESPONSES[group][size]
        if len(word) == 1 and group == 2:
            value += 0.18
        if any(c in I_LETTERS for c in opening):
            value -= 0.06
        if plain(token) in SUFFIXES:
            value -= 0.19 if group == 1 else 0.12
    elif token.isalpha() and token.lower().startswith('y'):
        has_vowel = any(c in VOWELS for c in plain(word))
        n = len(token)
        if word and not has_vowel:
            value = (0.19 if n == 2 else 0.38 if 3 <= n <= 4
                     else 0.03)
        elif word:
            value = -0.08 if n <= 2 else 0.05
    elif token.strip().lower() == 'al' and word.lower() == 'et':
        value = 0.72

    # Keep at most 64 contiguous word letters; boundaries reset this history.
    tail = len(token)
    while tail and token[tail - 1].isalpha():
        tail -= 1
    word = (word + token if tail == 0 else token[tail:])[-64:]
    return (doc, word), float(value)

"""Sparse lexical entity/body signal.

The strongest negative response is to 'entity' and 'entities'. Spacing,
capitalization, and code delimiters change its strength. Smaller responses
mark the fragment 'ent', identity/wholeness words, selected body/entity
terms in other languages, and 'estate' specifically after 'real'.
Split UTF-8 tokens completing certain mathematical letters receive a
positive signal. Everything else receives zero; no later token is inspected.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    name = word.lstrip('._/@\\(<-')
    lower = name.lower()
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2].strip()
    value = 0.0

    if lower in {'entity', 'entities'}:
        plural = lower == 'entities'
        if token.startswith(' '):
            value = -5.5 if plural else -6.8
        elif word.startswith('.'):
            value = -5.0 if plural else -6.5
        elif word.startswith(('/', '\\', '(', '<', '@')):
            value = -3.8 if plural else -4.5
        else:
            value = -4.2 if plural else -5.3
            if name[:1].isupper() and not plural:
                value = -6.7
        if name.isupper():
            value = -4.5
    elif lower == 'getentity':
        value = -4.7
    elif lower.startswith('entity') or lower.endswith('entity'):
        value = -1.2  # EntityManager, ResponseEntity, and similar compounds.
    elif lower in {'ent', 'ents'}:
        if word.startswith('.'):
            value = -2.1
        elif token[:1].isspace():
            value = -1.55
        elif name == 'Ent':
            value = -1.9
        else:
            value = -0.23
    elif lower in {'identity', 'identities', 'entitled'}:
        value = -1.05
    elif lower in {'entirely', 'entirety', 'wholly'}:
        value = -0.85
    elif lower in {'entire', 'fully'}:
        value = -0.23
    elif lower == 'estate':
        value = -0.9 if previous.lower() == 'real' else -0.06
    elif lower in {'body', 'embodiment'}:
        value = -0.17
    elif lower in {'bodies', 'embodiments'}:
        value = -0.3
    elif (lower == 'entidad' or
          previous.lower().lstrip('._/') + lower in
          {'entidade', 'entidades', 'entidad'}):
        value = -2.2
    elif word == '体':
        value = -1.95
    elif word == '體':
        value = -1.4
    elif word in {'实体', '實體'}:
        value = -4.9
    elif word in {'主体', '主體'}:
        value = -3.5
    elif word in {'整体', '整體'}:
        value = -1.2
    elif word in {'载体', '載體', '立体', '立體', '身份', '体制', '一体'}:
        value = -0.85
    elif word == '체':
        value = -1.6
    elif lower == 'thể':
        value = -0.8
    elif '\ufffd' in token:
        char = prefix.text_prefixes[-1][-1]
        if char == 'ℤ':  # The integer number-system symbol.
            value = 1.8
        elif char in 'ℂℚ':  # Complex and rational number systems.
            value = 0.65
        elif 0x1D44E <= ord(char) <= 0x1D49B:
            # Italic lowercase and bold-italic mathematical letters.
            value = 1.0
    return None, value

programs.haiku:
"""Component layers.0.mlp.down_proj:839: an 'entity' detector.

What it does: this component writes a strong negative signal into the residual stream
whenever the model reads the word "entity" (the standalone word, plural, capitalised, or
as the tail of a camel-case name like getEntity). Its response is much weaker on a few
related pieces: the split-off word stub " ent" / " Ent" / " ENT" (as in "ent|ire" or
"ent|wicklung"), the words "identity" and "estate", the words "entitled" and "entirely",
and Chinese/Japanese/Korean characters for body or collective/whole (体, 體, 团, 主体,
整体, 集体, 群体, 全体). Everything else is predicted as 0 (the component is quiet).

The program is a plain lookup on the newest token's text: no state is carried between
positions. Predicted activation values are the average activations measured on training
text (entity ~ -6.8, body characters ~ -2, ent-stub ~ -1.6, identity ~ -1.1, entitled ~ -0.9).
"""

READS = ()

ENTITY_WORDS = {"entity", "entities"}
IDENTITY_WORDS = {"identity", "identities"}
ESTATE_WORDS = {"entitled", "entirely", "estate"}
BODY_CHARS = set("体體团團")
BODY_WORDS = {"主体", "整体", "集体", "群体", "全体"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().strip(".").lower()
    if word in ENTITY_WORDS or tok.strip().strip(".").endswith("Entity"):
        return None, -6.5
    if word in BODY_WORDS or (len(word) == 1 and word in BODY_CHARS):
        return None, -2.0
    if word == "ent" and tok.startswith(" "):
        return None, -1.6
    if word in IDENTITY_WORDS:
        return None, -1.1
    if word in ESTATE_WORDS:
        return None, -0.9
    return None, 0.0

programs.luna:
"""Predict a strong negative value for "entity" and weaker related word pieces."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.casefold().strip()

    # The clear outlier is the word "entity" (including plural and code names).
    if "entity" in word:
        return None, -5.8 if word.endswith("entities") else -6.6

    # A weaker response tracks English word pieces beginning with "ent-".
    if token.casefold() == " ent":
        return None, -1.7
    if token == "Ent":
        return None, -2.0
    if word in {"ent", "entirely", "entitled", "identity", "identities"}:
        return None, {
            "ent": -0.5,
            "entirely": -0.9,
            "entitled": -1.0,
            "identity": -1.2,
            "identities": -1.0,
        }[word]
    if token in {"体", "體"}:
        return None, -2.0
    return None, 0.0

programs.haiku:
"""Layer-0 MLP neuron 840 (down_proj), read as a detector for determiner-like words.

It writes a positive value when the current token is:
  - "each" (English; the strongest and most reliable case, about 1.4)
  - "following" right after "the" (about 0.85; "following" elsewhere is about 0)
  - a demonstrative meaning "this/these" in Indonesian, Vietnamese, Hebrew or
    Japanese (ini, tersebut, itu, này, đó, ấy, זה, הזה, これ; about 2)
  - a which/what word in Vietnamese, Thai, Korean or Indonesian (nào, gì, อะไร,
    ใด, ไหน; about 2.5 to 3)
  - an "other / new / next / first" word in Vietnamese, Thai, Malay, Arabic or
    Hebrew (khác, lain, mới, cũ, baru, جديد, חדש, הבא; about 1.5)
  - a pointing or anaphoric English word: below, itself, etc, thereof, herein,
    alone, ones, follows (about 0.3 to 0.9)
  - the code tokens "Impl" (about 2.2) and "Factory" (about 0.8)
It writes a small negative value for some code and chat-markup tokens, and 0 for
everything else. English this, that, these, other, another, new, first, many and
some are about 0 here, so the neuron is not a general determiner detector.

Why: the activation is a token-identity signal that is rare and large. Most of the
variance comes from the few tokens above, so a short word list captures about a fifth
of the variance on eval; the rest is small and spread across the vocabulary.
"""

READS = ()

EACH = {" each", " Each", "each", "Each"}

THIS_WORDS = {
    " ini", " Ini", " itu", " tersebut", " này", " đó", " Đó", " ấy", " Đây",
    " זה", " הזה", " זו", " הזו", " אלה", " אלו", "これ", "こちら",
}

WHICH_WORDS = {
    " nào": 3.0, " gì": 3.0, "อะไร": 3.0, "ใด": 2.7, "ไหน": 2.5,
    "ใคร": 1.3, " apa": 1.3, "무엇": 2.0,
}

OTHER_WORDS = {
    " khác", " lain", " mới", " cũ", " baru", " thứ", " đầu",
    " آخر", " أخرى", " جديد", " الأولى", " التالي",
    " אחר", " אחרות", " חדש", " הבא",
}

POINTING = {
    " below": 0.5, " itself": 0.65, " themselves": 0.3, " etc": 0.8,
    " thereof": 0.9, " therein": 0.7, " herein": 0.65, " alone": 0.9,
    " ones": 0.35, " respectively": 0.3, " yourself": 0.25, " follows": 0.35,
    "Impl": 2.2, " Factory": 0.8,
}

MARKUP_NEG = {
    "/workspace": -0.3, "<tool_response>": -0.24, "<think>": -0.27,
    "<tool_call>": -0.13, ".println": -0.3, "-plugin": -0.3, " и": -0.14,
}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in EACH:
        value = 1.4
    elif tok == " following":
        value = 0.85 if prev in (" the", "The", " The") else 0.0
    elif tok in THIS_WORDS:
        value = 2.0
    elif tok in WHICH_WORDS:
        value = WHICH_WORDS[tok]
    elif tok in OTHER_WORDS:
        value = 1.5
    elif tok in POINTING:
        value = POINTING[tok]
    elif tok in MARKUP_NEG:
        value = MARKUP_NEG[tok]
    else:
        value = 0.0
    return carry, float(value)

"""layers.0.mlp.down_proj:841 -- the sentence-opening word detector.

Fires on the first word of a sentence in running prose: the word right after a full
stop, question or exclamation mark (or a closing quote or bracket after one), or at the
start of a line. Its size depends on the kind of word:
  * transition or prepositional openers (This, In, For, To, If, When, However, One, Based) : strong
  * subject pronouns and articles (He, We, They, The, There, A) : moderate
  * I : weak
  * any other ordinary capitalised word (not all-caps, not a name-like label): weak
Starts after a line break or a space count less than starts after a full stop.
Everything else (mid-sentence words, punctuation, code, headings) predicts 0.
