READS = ()

OPENERS = {
    "This", "That", "These", "Those", "In", "On", "At", "To", "For", "By", "With",
    "From", "As", "If", "When", "While", "Once", "Since", "After", "Although", "Because",
    "And", "But", "So", "However", "Thus", "Also", "What", "How", "Here", "It", "Moreover",
    "Furthermore", "Given", "According", "Through", "Where", "Which", "One", "Based",
    "Besides", "Now", "Can", "Is", "Are", "Let", "Of", "Not", "All",
}
SUBJECTS = {"He", "She", "We", "They", "The", "There", "You", "A", "An", "His", "Its", "Our"}


def boundary_strength(prev):
    """How much the previous token marks a sentence or line start."""
    if "\n" in prev or prev.strip(" \xa0\t") == "":
        return 0.6  # line break or indentation
    core = prev.rstrip("\"'”’)]* ")
    return 1.0 if core[-1:] in (".", "!", "?") else 0.0


def word_level(word):
    if word in OPENERS:
        return 1.7
    if word in SUBJECTS:
        return 1.0
    if word == "I":
        return 0.4
    if len(word) > 1 and word[0].isupper() and word[1:].islower() and word.isalpha():
        return 0.45  # ordinary capitalised word
    return 0.0


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0  # a new document starts with no context
    strength = boundary_strength(prefix.token_strings[-2])
    if strength == 0.0:
        return None, 0.0
    return None, strength * word_level(prefix.token_strings[-1].strip())

