import unicodedata

CLAUSE_OPENERS = {
    "in", "if", "this", "that", "these", "when", "while", "although",
    "because", "since", "before", "after", "as", "but", "and", "or",
    "for", "to", "with", "on", "at", "among", "what", "how", "according",
    "which", "once", "rather", "by", "from",
}
TRANSITION_OPENERS = {
    "however", "therefore", "thus", "furthermore", "also", "alternatively",
    "then", "now", "first", "next", "eventually", "so", "let", "here",
    "there",
}
NOUN_PHRASE_OPENERS = {
    "the", "a", "an", "some", "another", "one", "my", "our", "his",
    "your", "their", "all", "no", "any",
}
PRONOUN_OPENERS = {"i", "we", "he", "she", "it", "you", "they", "who"}


def step(carry, prefix, upstream):
    pos = prefix.position
    doc = prefix.document_ids[pos]
    tail = "" if carry is None or carry[0] != doc else carry[1]

    text = prefix.token_strings[pos]
    first = next((ch for ch in text if ch.isalpha()), "")
    opener = bool(first) and (
        first.isupper() or unicodedata.category(first) == "Lo"
    )
    word = text.strip().casefold()
    before = tail.rstrip()
    while before and before[-1] in "\"'”’)]}»":
        before = before[:-1].rstrip()
    mark = before[-1:] if before else ""

    value = 0.0
    if mark == ".":
        if opener:
            if word in CLAUSE_OPENERS:
                value = 1.65
            elif word in TRANSITION_OPENERS:
                value = 1.15
            elif word in NOUN_PHRASE_OPENERS or word in PRONOUN_OPENERS:
                value = 0.9
            else:
                value = 0.66
        elif first and first.islower():
            value = -0.14
    elif mark in ("!", "?", "。", "！", "？"):
        if opener:
            value = 0.17
        elif first and first.islower():
            value = 0.02

    return (doc, (tail + text)[-16:]), float(value)

