DIACRITICS = "ăâîșțĂÂÎȘȚ"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent = ""
    else:
        recent = carry[1]
    recent = (recent + token)[-120:]

    piece = token.casefold().strip()
    if piece == "ul":
        value = 0.7
    elif piece in {"care", "fi"} and any(mark in recent for mark in DIACRITICS):
