REPRESENTATIONS = {
    'form': (-0.04, 0.95), 'forms': (-0.02, 0.48),
    'manner': (0.0, 0.66), 'sense': (-0.02, 0.73),
    'shape': (-0.04, 0.36), 'style': (-0.03, 0.41),
}
