    doc = prefix.document_ids[-1]
    past, last_value = ([], 0.0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    words = [s.strip().lower() for s in past]
    prev = words[-1] if words else ''
    earlier = words[-2] if len(words) > 1 else ''
    distance = next((i for i, w in enumerate(reversed(words), 1) if w == 'in'), 0)
    value = -0.001

    if token in DELIMITERS:
        value = DELIMITERS[token]
    elif token.startswith(' ') and word in ('way', 'ways'):
        value = -0.14 if word == 'way' else -0.10
        if prev == 'the':
            value = -0.30
            value = {'along': -0.85, 'by': -0.62, 'on': -0.44}.get(earlier, value)
        elif prev in ('by', 'under'):
            value = -0.51 if prev == 'by' else -0.75
        if 1 <= distance <= 4:
            if distance == 1:
                value = -1.10
            elif distance == 2:
