                         'this': -0.57, 'some': -0.57,
                         'another': -0.55, 'other': -0.55}.get(prev, -0.74)
            else:
                value = -0.52 * 0.52 ** (distance - 3)
                if distance == 3 and earlier == 'such' and prev == 'a':
                    value = -0.66
    elif token.startswith(' ') and word in REPRESENTATIONS:
        value, peak = REPRESENTATIONS[word]
        if word == 'form':
            if prev == 'the':
                value = -0.27
                if earlier in ('take', 'takes', 'took', 'taking'):
                    value = -0.78
                elif earlier in ('have', 'has', 'had'):
                    value = -0.43
            elif prev == 'to':
                value = -0.20
        if 1 <= distance <= 4:
            modifier = {'the': 1.0, 'a': 0.68, 'an': 0.68, 'any': 0.68,
                        'this': 0.42, 'that': 0.55, 'some': 0.43}.get(prev, 0.32)
            if word in ('shape', 'style', 'forms'):
                modifier = 0.83
            scale = 1.0 if distance == 1 else modifier if distance == 2 else (
                0.35 * 0.5 ** (distance - 3))
            value = -peak * scale
    elif token.startswith(' ') and word in IN_PHRASES:
        value, direct = IN_PHRASES[word]
        if distance == 1:
            value = direct
            if word == 'particular' and past[-1].strip() == 'In':
                value = -0.71
        elif distance == 2:
            value = {'fact': -0.09, 'particular': -0.25, 'range': -0.35,
                     'respect': -0.17, 'common': -0.24,
                     'following': -0.29}[word]
