    elif token == ' know':
        value = -0.08
        if prev == 'to':
            value = -0.40
            if earlier in ('want', 'wants', 'get', 'got', 'like'):
                value = -0.65
        elif prev in ('should', 'must'):
            value = -0.32
        elif prev in ("'t", '’t'):
            value = 0.02
        elif prev == 'i':
            value = -0.035
        elif prev == 'you':
