    elif token == ' of':
        value = -0.008
        if prev == 'form':
            value = last_value - 0.13
        elif prev in ('shape', 'style'):
            value = last_value - 0.10
        elif prev == 'sense':
            value = 0.48 * last_value - 0.07
        elif prev in ('manner', 'forms'):
            value = 0.7 * last_value - 0.05
        elif prev == 'way':
