"""Recognize text/table manipulation and dollar-variable notation.

Emit negative values for replacement, searching, splitting/joining strings,
spreadsheet terminology, and iteration. Method/identifier syntax strengthens
several responses. Recent text distinguishes programming dollars from LaTeX
and spreadsheet formulas from other formulas. Unmatched tokens get zero; finer lexical
and contextual variation is deliberately left unexplained.
"""
import re

READS = ()
CODE = re.compile(
    r'<\?php|->|=>|\b(?:foreach|echo|protected|public|private|const|'
    r'var|console|def|php|bash|curl|printf|npm|git|chmod)\b|'
    r'\bfunction\s+\w+\s*\(|\bmy\s+\$|'
    r'\$[A-Za-z_]\w+\s*(?:=|->)|;\s*(?:\n|$)')
LATEX = re.compile(
    r'\\(?:frac|sqrt|math|theta|sigma|epsilon|lim|cdot|text|alpha|beta)')
SPREADSHEET = re.compile(
    r'\b(?:excel|spreadsheet|workbook|xlsx|dataframe|pandas|vlookup|'
    r'countif|sumif|sheet\d+|cell\s+[a-z]\d+)\b', re.I)
STRING_OPERATIONS = set('''split join substring trimspace strcpy strcmp
    findall replaceall replacefirst indexof readlines getline'''.split())
TABLE_NAMES = set('excel csv xlsx spreadsheet workbook dataframe'.split())
TABLE_PARTS = set('cell cells row rows column columns sheet sheets'.split())
ITERATION = set('loop loops foreach iterate iterating range arange linspace'.split())


def predict(token, recent):
    s = token.strip()
    w = s.lstrip('._(/-').lower()
    method = s.startswith('.')
    identifier = s.startswith('_') or bool(s and token == s)
    if '$' in s and '$$' not in s:
        code = bool(CODE.search(recent.replace('\\n', '\n')))
        if s == '$':
            if not recent:
                return -0.30
            return 0.10 if LATEX.search(recent) else (-0.46 if code else -0.04)
        if s.endswith('\\$'):
            return -0.23
        if '${' in s:
            return -0.80 if any(c in s for c in '\"\'`}') or code else -0.30
        if s.startswith('$') and s[1:].isidentifier():
            return -0.10 if len(s) == 2 else -0.60
        return -0.60 if s.endswith('$') and s[:-1] and s[-2] in '(\"\'`[:=/' else 0.0
    if re.fullmatch(r'replac(?:e|ed|es|ing|ement|ements)', w):
        if s.startswith('_'):
            return -1.33
        if method:
            return -0.97
        return -0.85 if w == 'replace' and identifier else -0.43
    if w in {'grep', 'regex', 'regexp', 'xpath', 'awk'}:
        return -0.65
    if s == 'sed':
        return -0.40
    if w in STRING_OPERATIONS:
        return -0.80 if method else (-0.44 if identifier else -0.24)
    if w == 'sprintf':
        return -1.0
    if w in {'printf', 'fprintf', 'scanf', 'sscanf'}:
        return -0.44 if method else -0.33
    if w in TABLE_NAMES:
        return -0.80 if method or s.startswith('_') else -0.46
    if w == 'df':
        return -0.36
    if w in {'formula', 'formulas', 'formulae', '公式'}:
        return -1.0 if SPREADSHEET.search(recent) else -0.40
    if w in TABLE_PARTS:
        return -0.51 if SPREADSHEET.search(recent) else -0.14
    if w in {'query', 'queries', 'qry'} or (w == 'where' and s.isupper()):
        return -0.35
    if w in ITERATION:
        if w == 'range' and re.search(r'\bin\s*$', recent):
            return -0.89
        return -0.43 if identifier or method or w == 'foreach' else -0.26
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
