programs.luna:
"""A lexical sketch of code and data-editing vocabulary.

It predicts small negative activations for PHP dollar signs and terms used
for searching, replacing, querying, looping, and spreadsheet calculations.
"""

import re

READS = ()

EDITING = {"replace", "grep", "regex", "regexp", "xpath"}
DATA_WORK = {
    "formula", "cell", "csv", "query", "queries", "join", "loop",
    "range", "randint", "getjsonarray",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    lower = token.lower()
    words = set(re.findall(r"[a-z]+", lower))

    if re.search(r"(?<![A-Za-z0-9])\$", token):
        return None, -0.55 * 0.35
    if "replace" in lower:
        return None, -0.90 * 0.35
    if words & EDITING:
        return None, -0.55 * 0.35
    if "getjsonarray" in lower.replace("_", ""):
        return None, -0.70 * 0.35
    if words & DATA_WORK:
        return None, -0.43 * 0.35
    return None, 0.0

programs.sol:
"""Lexical scope and relation markers, especially in Chinese and Japanese.

Large positives recognize 'overall', Chinese standpoint phrases, and Japanese
postpositions. Smaller rules cover case/purpose expressions and protocol tags.
This approximation uses spelling, plus short context for 'speaking of' and
'for the purpose of'; it is not a general semantic or grammatical analysis.
"""
READS = ()

PROTOCOL = {
    '<|endoftext|>': 0.79,
    '<|im_start|>': 0.08,
    '<|im_end|>': -0.05,
    '<think>': 0.18,
    '</think>': -0.08,
    '<tool_call>': -0.13,
    '</tool_call>': -0.27,
    '<tool_response>': -0.42,
    '</tool_response>': 0.12,
}


def lexical_value(token):
    w = token.strip()
    if w in PROTOCOL:
        return PROTOCOL[w]
    if w.lower() == 'overall':
        return 1.75 if w[0].isupper() else 1.51

    # Chinese standpoint, appearance, motion, and temporal expressions.
    if w.endswith(('来说', '來說')):
        return 5.8 if w == '来说' else 5.1 if w == '來說' else 3.6
    if w.endswith('而言'):
        return 5.6
    if w == '来看':
        return 3.45
    if w in {'来', '來'}:
        return 1.25
    if w in {'起来', '起來', '下来', '下來', '以来', '用来', '看来'}:
        return 1.0
    if w in {'看起来', '看起來'}:
        return 1.5 if w == '看起来' else 2.0
    if w in {'本身', '情况下', '相比'}:
        return 1.4
    if w in {'方面', '的话', '总体', '整体', '總體', '整體'}:
        return 0.85
    if w in {'时', '時', '时候', '時候', '目前', '之后', '之後'}:
        return 0.45
    if w in {'的时候', '的時候'}:
        return 0.63
    if w in {'后', '後', '以后', '以後', '去', '看'}:
        return 0.32

    # Japanese postpositions: for a person, in, concerning, and by means of.
    if w.startswith('にとって'):
        return 4.2
    if w == 'において':
        return 2.95
    if w in {'における', 'に対して', 'に関して'}:
        return 2.0
    if w in {'について', 'については', 'に関する', 'によって',
             'による', 'により', 'での', 'への'}:
        return 1.5
    if w in {'で', 'です'}:
        return 0.91
    if w in {'では', 'である', 'として', 'へ', 'という', 'なら'}:
        return 0.68
    if w in {'に', 'には', 'にも'}:
        return 0.43
    if w in {'ため', '場合', 'ことです', 'ものです', 'としては', '非常に'}:
        return 1.5
    if w in {'のです', 'んです', 'より', 'よりも', 'のみ', 'であり'}:
        return 0.85
    if w.endswith('場合'):
        return 2.3
    if w.endswith(('ために', 'だけで')):
        return 1.1
    if w in {'ので', 'だけ', 'まで'}:
        return 0.25
    if w.startswith('に'):
        return 1.4 if w == 'にして' else 1.15 if w == 'になって' else 0.6
    if w.endswith(('で', 'くて')):
        return 0.9
    if w.endswith('に'):
        return 0.55
    # Japanese copular and predicate endings, and grammatical particles.
    if w in {'でした', 'だった', 'だろう', 'でしょうか'}:
        return 0.65
    if w.startswith('です'):
        return 0.36
    if w.startswith('であ') or w == 'ではなく':
        return 1.05
    if w in {'が', 'も', 'ある', 'いる', 'した'}:
        return -0.20
    if w in {'は', 'を'}:
        return -0.07
    if w == 'の':
        return 0.05
    if w == 'ん':
        return 0.3
    if w.endswith('している'):
        return -0.4

    # Korean dative/locative particles and copulas.
    if w in {'에게', '입니다', '보다'}:
        return 1.25
    if w in {'대한', '이다'}:
        return 0.94
    if w in {'에', '에서', '에서는', '때', '대해'}:
        return 0.50
    if w in {'으로', '부터'}:
        return 0.30
    if w in {'가', '은', '는', '을', '도'}:
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = lexical_value(token)
    if word in {'来说', '來說', '而言'}:
        if previous in {'具体', '具體'}:  # 'specifically speaking'
            value = 3.9
        elif '对' in tail or '對' in tail:  # someone's standpoint
            value = 5.6 if word == '來說' else 6.3
    if word == 'の' and previous == 'ため':  # 'for the purpose of'
        value = 0.75
    if word == ',' and previous.lower() == 'overall':
        value = 0.22
    return (doc, (tail + token)[-40:], word), value

