programs.haiku:
"""layers.0.mlp.down_proj:850 as a small word lexicon.

Layer 0's MLP output direction 850 is switched on or off by specific words, not by any
clean concept. This program lists the words it reacts to most reliably, grouped by the
kind of word they are, and predicts the component's activation from the current token
alone. Everything else is predicted as 0.

Groups (value = predicted activation):
  - Chinese "not / cannot" words (没, 无法, 不会, 不能): strongest, about +0.7.
  - Assist/aid words (assist, assistance, 协助): about +0.35.
  - Degree / extent words (frequently, considerable, throughout, numerous, various,
    excellent): about +0.3.
  - Chinese forceful-action adverbs and verbs (大力, 大大, 早已, 强化, 反对, 拒绝): about +0.5.
  - Chat-template tags: </tool_response> +0.3, <tool_response> -0.17, <think> -0.3.
"""
READS = ()

NOT_CANNOT_ZH = {"没", "沒", "无法", "無法", "不会", "不會", "不能"}
ASSIST = {"assist", "assisted", "assists", "assistance", "aid", "协助", "協助"}
DEGREE_EN = {"frequently", "numerous", "considerable", "substantial", "throughout",
             "worldwide", "excellent", "absolutely", "various", "nationwide"}
FORCEFUL_ZH = {"大力", "大大", "大幅度", "早已", "仍然", "确保", "强化", "反对", "拒绝"}
TAG_VALUE = {"</tool_response>": 0.3, "<think>": -0.3, "<tool_response>": -0.17}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in NOT_CANNOT_ZH:
        return None, 0.7
    if word in FORCEFUL_ZH:
        return None, 0.5
    if word in ASSIST:
        return None, 0.35
    if word in DEGREE_EN:
        return None, 0.3
    return None, TAG_VALUE.get(word, 0.0)

programs.sol:
"""A partial spelling explanation for short fragments inside split Latin words.

Vowel-led, vowel-ended fragments are negative, with strength depending on
vowel density, velar/liquid consonants, and nearby vowel letters. Closed
-ik fragments and final y are positive. Small corrections cover English
suffixes and explicit chat/code markers; most text is zero. Signs and
levels approximate observed training activations.
These are local spelling cues, not a classifier of languages or meanings.
"""
READS = ()
VOWELS = 'aeiouy'  # y counts as a vowel for these spelling shapes
INFLECTIONS = {'s', 'ed', 'ing', 'er', 'est'}
DERIVATIONS = {'ly', 'able', 'ive', 'ity', 'less'}


def fragment_value(t, previous, capital):
    near_vowel = len(previous) >= 2 and previous[-2] in 'aeiou'
    if t.endswith('k') and t[0] in 'aeiou':
        return 0.219 if t == 'ik' else 0.04
    if t == 'y':
        return 0.017 if capital else 0.10
    if len(t) == 1 and t in VOWELS:
        if near_vowel and len(previous.strip()) <= 4:
            return -0.054 if t == 'i' else -0.12
        if previous[-1] in VOWELS:
            return -0.012 if t == 'i' else -0.092
        return -0.015
    if len(t) >= 2 and t[0] in 'aeiou' and t[-1] in 'aou':
        if 'i' in t:
            return -0.049 if near_vowel else -0.007
        middle = t[1:-1]
        if 'g' in middle and t[0] == t[-1] and t[0] in 'au':
            return -0.48 if t[0] == 'u' else -0.40
        if len(t) == 2:
            if t[0] == 'u':
                return -0.411 if t[-1] == 'a' else -0.153
            return -0.08
        if all(c in VOWELS for c in t):
            return -0.482 if near_vowel else -0.391
        if 'd' in middle or 't' in middle:
            return -0.05
        if near_vowel and previous.endswith('k'):
            return -0.346
        if len(t) == 4:
            return -0.079 if near_vowel else -0.021
        if middle == 'r':
            if 'e' in t:
                return -0.09 if near_vowel else -0.04
            return -0.30 if near_vowel else -0.16
        if middle == 'k':
            return -0.369 if near_vowel else -0.209
        return -0.152 if near_vowel else -0.055
    if t.endswith('i'):
        if len(t) == 3 and t[0] in VOWELS and t[1] not in VOWELS:
            if t[1] == 'k':
                return -0.407 if near_vowel else -0.173
            return -0.06
        return -0.109 if 'h' in t else -0.009
    if t in INFLECTIONS:
        return 0.026
    if t in DERIVATIONS:
        return -0.022
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    carry = (doc, s.lower())
    if s in {'<|im_start|>', '<|im_end|>'}:
        return carry, -0.0175 if s == '<|im_start|>' else -0.0315
    if s == '<think>':
        return carry, 0.058
    if s == '\\n':
        return carry, -0.029
    if s.strip() == '=>':
        return carry, 0.064
    t = s.lower()
    if not (1 <= len(t) <= 4 and t.isascii() and t.isalpha()
            and previous and previous[-1].isascii() and previous[-1].isalpha()):
        return carry, 0.0
    return carry, fragment_value(t, previous, s[0].isupper())

programs.haiku:
"""Layer-0 MLP down_proj component 853: a "relation" and "system" word detector.

The component reads the current token and writes a fixed-size "this is a relation word" or
"this is a system word" signal into the residual stream. It is lexical, not contextual:
it responds to the word itself, in English and in other languages, and predicts 0 for
almost every other token.

  - the Chinese character 系 (system / series / department, as in 系统, 色系, 舞蹈系): strongest
  - 关系, 關係, 係, 联系, 关联 (relation, connection), and Vietnamese hệ / Korean 계: strong
  - relation, relations, relationship, relationships (any capitalisation): strong
  - system, systems, System, sys, systematic (also 体系, 系统, sistema, систем): medium
  - "operating system" (the computer OS sense) is weak, as is the "system" in "computer systems"

Everything else predicts 0.
"""

READS = ()

SERIES_CHAR = {"系": 6.5}
RELATION_ZH = {"关系", "關係", "係", "联系", "關聯", "关联", "的关系", "hệ", "계", "관계"}
RELATION_WORDS = {"relation", "relations", "relationship", "relationships"}
SYSTEM_WORDS = {"system", "systems", "sys", "systemic", "systematic"}
SYSTEM_OTHER = {"系统", "系統", "体系", "體系", "系数", "sistema", "systema"}
RUSSIAN_STEMS = ("систем", "связ")
OS_CONTEXT = {"operating", "computer", "file"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if token in SERIES_CHAR:
        return carry, SERIES_CHAR[token]
    if token in RELATION_ZH or word in RELATION_ZH:
        return carry, 3.3
    if word in RELATION_WORDS:
        return carry, 1.8
    if word in SYSTEM_WORDS:
        return carry, 0.2 if previous in OS_CONTEXT else 1.3
    if token in SYSTEM_OTHER or word in SYSTEM_OTHER:
        return carry, 1.3
    if word.startswith(RUSSIAN_STEMS):
        return carry, 1.3
    return carry, 0.0

