programs.sol:
"""A short-range spelling response: the token after a n-like ending.

Repeated n has a large negative response. Most other consonant onsets,
especially l, m, r and b, are positive. Short tokens, vowel+n endings,
and absence of a word boundary strengthen the response. Letter names
and partial transliterations extend the same rule to several scripts.
A weak opposite response remains elsewhere, with a negative response
for a lone n at document start. Exact words and distant context are ignored.
"""
import unicodedata

READS = ()

ONSET = {
    'b': 1.51, 'c': 0.39, 'd': -0.14, 'e': 0.05,
    'f': 0.96, 'g': 0.12, 'h': 0.75, 'j': 0.36,
    'k': 0.44, 'l': 2.01, 'm': 1.64, 'n': -2.09,
    'o': 0.03, 'p': 1.25, 'q': 0.81, 'r': 1.67,
    's': 0.39, 't': 0.13, 'u': -0.03, 'v': 0.89,
    'w': 1.22, 'x': 0.43, 'y': 0.28, 'z': 0.18,
    'sh': 1.31, 'st': 0.78, 'ft': 0.30, 'nt': -1.42,
    'vowel_l': 0.74, 'vowel_b': 0.35, 'soft_n': -0.84,
}
CYRILLIC = str.maketrans('нлрмбфпсхвктчдйзёеоаиуя',
                         'nlrmbfpshvktcdyzeeoaiuy')
GREEK = str.maketrans('νλρμβφπσςχκτδζαειου',
                      'nlrmbfpsshktdzaeiou')
ARABIC = str.maketrans('بفترزسشدقكلمنهويگ',
                       'bftrzssdqklmnhwyg')


def romanize(text):
    return text.lower().translate(CYRILLIC).translate(GREEK).translate(ARABIC)


def ends_in_n(text):
    if not text:
        return False
    letter = text[-1]
    if letter in 'nNнНνΝنンんนन':
        return True
    name = unicodedata.name(letter, '')
    return name.startswith('HANGUL SYLLABLE ') and name.endswith('N')


def onset(text):
    if not text:
        return ''
    letters = romanize(text)
    pair = letters[:2]
    if pair in ('sh', 'st', 'ft', 'nt'):
        return pair
    if pair in ('el', 'ol'):
        return 'vowel_l'  # Vowel followed by the liquid l.
    if pair == 'ob':
        return 'vowel_b'
    if text.startswith(('ня', 'ню')):
        return 'soft_n'
    name = unicodedata.name(text[0], '')
    if name.startswith(('KATAKANA LETTER ', 'HIRAGANA LETTER ',
                        'HANGUL SYLLABLE ')):
        return name.split()[-1][0].lower()
    return letters[0]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    body = token.lstrip(' \t\r\n-_.,/(')
    response = ONSET.get(onset(body), 0.0)
    response /= 1 + 0.45 * max(0, len(body) - 2)
    if token != body:
        response *= 0.06 if token[:1].isspace() else 0.38
    if body.isupper():
        response *= 0.75

    value = -0.023 * response  # Small opposite-sign background response.
    if not previous and token.lower() in ('n', 'н', 'ν'):
        value = -1.65
    elif ends_in_n(previous):
        value = response / (1 + 0.28 * max(0, len(previous.strip()) - 3))

        ending = romanize(previous)
        if ending.endswith('\\n'):
            value *= 0.20  # An escaped newline is not an ordinary n ending.
        elif ending[-2:-1] in ('a', 'e', 'u', 'y', 'ü'):
            value *= 1.31
        elif ending[-2:-1] in ('i', 'o', 'ö'):
            pass
        elif ending[-2:-1].isalpha():
            value *= 0.56
        else:
            value *= 0.63
        if previous.strip().isupper():
            value *= 1.56
    return (doc, token), float(value)

