programs.sol:
"""Approximate punctuation-boundary responses, not all lexical variation.

Bare document-initial commas/periods and repeated commas/periods are positive.
Tokens following commas are negative in Chinese clauses and quoted lists
or arguments. Chinese clause openers have different strengths; a new quote is
more negative inside a tool-call block. There are small priors for empty
parentheses and chat/tool delimiters, and a near-zero default elsewhere.
State consists only of the previous token and whether a tool-call block is open;
it resets whenever the document changes.
"""
READS = ()

# Clause-opening copulas, additive links, and purpose/prepositional phrases.
STRONG_LINKS = ('是', '也', '同时', '同時', '为', '為')
PREPOSITIONAL_LINKS = ('以', '对', '對', '有', '由')
SUBJECTS = ('我', '你', '您', '他', '她', '它', '这', '這', '那')
CONTRAST_OR_CONDITION = ('但', '如果', '如', '而', '所以')
START_PUNCTUATION = {
    ',': 1.028, '.': 0.549, '，': 0.766, '。': 0.449,
    '"': 0.241, ';': 0.189, ':': 0.108, '?': 0.200, '(': -0.167,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    body = token.strip()
    first = carry is None or carry[0] != doc
    prev = '' if first else carry[1].rstrip()
    in_tool_call = False if first else carry[2]
    is_han = any('\u3400' <= c <= '\u9fff' for c in body)
    value = -0.002
    if first:
        value = START_PUNCTUATION.get(token, -0.020)
    elif body in (',', '，') and prev.endswith((',', '，')):
        value = 0.54
    elif body == '.' and prev.endswith('.'):
        value = 0.30 if token.startswith(' ') else 0.05
    elif prev.endswith((',', '，')) and is_han:
        if body.startswith(STRONG_LINKS):
            value = -0.41
        elif body.startswith(PREPOSITIONAL_LINKS):
            value = -0.30
        elif body.startswith(SUBJECTS + CONTRAST_OR_CONDITION):
            value = -0.10
        else:
            value = -0.18
    elif prev.endswith(('\",', "',")) and body:
        if body == '"':
            value = -0.226 if in_tool_call else -0.160
        elif body == "'":
            value = -0.125
        elif body in ('()', '\\', '&', '$'):
            value = {
                '()': -0.30, '\\': -0.235, '&': -0.365, '$': -0.185,
            }[body]
        elif body == 'function':
