QUANTITY = {
    'less': 1.30, 'most': 0.75, 'much': 0.78, 'some': 0.98,
    'other': 0.92, 'others': 1.00, 'another': 0.73,
    'additional': 0.73, 'extra': 0.57, 'plus': 0.39,
    'greater': 0.37, 'fewer': 0.41, 'few': -0.24,
    'highly': 0.71, 'increasingly': 1.59, 'mostly': 0.46,
    'anymore': 0.77, 'whatever': 0.53,
}
RELATIONS = {'how': 1.13, 'what': 0.90, 'after': 0.78}

# Translations of more/increased degree, and related alternatives/amounts.
TRANSLATIONS = {
    'mehr': 1.65, 'más': 1.12, 'mais': 0.65, 'più': 0.62,
    'более': 1.90, 'больше': 0.66, 'もっと': 2.07,
    'أكثر': 1.46, 'moins': 0.60, 'weniger': 1.37,
    '更多': 3.28, '更多的': 2.46, '更多信息': 2.15,
    '更加': 2.43, '更': 0.59, '越来越多': 1.62,
    '其他': 0.77, '一些': 0.72, '别人': 0.44,
}


def response(token, previous):
    spelling = token.strip().lstrip('._/')
    word = spelling.lower()
    capital = spelling[:1].isupper()
    attached = not token[:1].isspace()

    if word == 'more':
        value = 5.20
        if capital:
            value = 6.30 if not attached else 6.95
        elif attached:
            value = 5.48
        if spelling.isupper():
            value = 4.70
        # Phrase-level uses differ from ordinary comparative 'more'.
        if previous in {'no', 'once'}:
            value *= 0.55
        elif previous == 'or':
            value *= 0.65
        elif previous in {'even', 'one', 'any', 'not', 'nothing'}:
            value *= 0.73
        elif previous == 'read':
            value *= 0.63
        elif previous == 'the':
            value *= 0.90
        return value

    value = QUANTITY.get(word, RELATIONS.get(word,
                         TRANSLATIONS.get(word, 0.0)))
    if word == 'other':
        if previous == 'each':
            value = 0.18
        elif previous == 'the':
            value = 0.49
        elif previous in {'some', 'all', 'any', 'no', 'every'}:
            value = 0.74
        if capital:
            value = 1.02
    elif word == 'how' and capital:
        value = 1.05 if attached else 0.95
    elif word == 'what':
        if capital:
            value = 0.60
        elif attached:
            value = 0.70
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    return (doc, token.strip().lower()), float(value)

