"""Estimate a short-ending response, not a word's meaning.

A letter-only token continuing an alphabetic fragment is positive when it
looks like a common inflection or a small word-ending fragment. Plural -s
is strongest. Longer preceding fragments amplify the response. Case and
vowel/consonant joining rules reduce unlikely endings. Whitespace, word
starts, punctuation, and digits receive zero. Longer Latin fragments have
a small negative response. State resets per document.
"""
import unicodedata

READS = ()

# Familiar inflections and derivational endings, across several languages.
INFLECTIONS = {'ed', 'er', 'es', 'en'}
ROMANCE_ENDINGS = {'as', 'os', 'ar', 'al'}
SHORT_ENDINGS = {
    'an', 'in', 'on', 'or', 'el', 'at', 're', 'em', 'et',
    'is', 'ie', 'ur', 'us', 'te', 'ic', 'ly', 'ers',
}
SLAVIC_CASES = {'и', 'у', 'е', 'ов', 'ами', 'ах', 'ам'}
SLAVIC_OTHER = {'о', 'ом', 'ой', 'ей', 'х', 'ми', 'ь'}
ARABIC_ENDINGS = {'ات', 'ة', 'ه'}
# Nasals, liquids, and t/d stops are stronger one-letter continuations.
NASALS_LIQUIDS_AND_T_D = frozenset('nmrltd')
DERIVATIONS = {'ion', 'ity', 'ment', 'ness', 'ism', 'ive', 'ally'}
CONSONANT_JOIN = INFLECTIONS | ROMANCE_ENDINGS | {'ing'}


def ending_strength(s):
    if s == 's':
        return 1.65
    if s in INFLECTIONS or s in {'a', 'i', 'o'}:
        return 1.05
    if s == 'e':
        return 1.3
    if s == 'ing':
        return 0.9
    if s in {'u', 'y'} or s in ROMANCE_ENDINGS:
        return 0.8
    if s in SHORT_ENDINGS:
        return 0.55
    if s in {'а', 'ы'}:
        return 1.35
    if s in SLAVIC_CASES or s in ARABIC_ENDINGS:
        return 1.1
    if s in SLAVIC_OTHER:
        return 0.75
    if s in NASALS_LIQUIDS_AND_T_D:
        return 0.65
    if s in DERIVATIONS:
        return 0.25
    if len(s) == 3 and s.isascii() and s.endswith('s'):
        return 0.12
    if all('LATIN' in unicodedata.name(c, '') for c in s):
        return {1: 0.35, 2: 0.14}.get(len(s), -0.01)
    return 0.01


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    tail = ''
    for c in reversed(previous):
        if not c.isalpha():
            break
        tail = c + tail
    value = 0.0
    # A title-cased piece starts a new word, including inside CamelCase.
    if token.isalpha() and tail and not (len(token) > 1 and token.istitle()):
        s, length = token.lower(), len(tail)
        # Nearly linear up to four letters, then only a small extra boost.
        scale = (0.3 + min(max(length - 1, 0), 3)
                 + 0.25 * min(max(length - 4, 0), 4)) / 3.3
        if s == 's' and (tail.isupper() or token.isupper()):
            scale *= 0.9
        elif tail.isupper() and not token.isupper():
            scale *= 0.4
        elif token.isupper():
            scale *= 0.7
        if tail[-1].lower() in 'aeiou' and s in CONSONANT_JOIN:
            scale *= 0.6
        value = ending_strength(s) * scale
    return (doc, token), float(value)

