            return 2.28 if token[:1].isspace() else 1.65
        if spelling[0].isupper():
            return 2.48 if token[:1].isspace() else 2.35
        if token[:1].isspace():
            return 2.5 if word == 'backs' else 2.1 if word == 'backing' else 2.31
        return 1.8
    if word in {'backward', 'backwards'}:
        return 1.11 if word == 'backward' else 1.0
    if word.startswith('background'):
        if word != 'background' or spelling.startswith('_'):
            return 0.65
        return 0.70 if not spelling.islower() else 0.83
    if word == 'behind':
        return 0.84
    if word.startswith('backlight'):
        return 1.47
    if word.startswith(('backdrop', 'backbone', 'backtrack')):
