READS = ()

# The word "back" and its inflections.
BACK_WORDS = {"back", "backs", "backed", "backing", "backer", "-back", "_back", ".back"}
# Chinese 背 (back of the body; to carry on the back); the compound words.
CHINESE_BACK = {"背", "背着", "背部", "背叛"}
# Compounds and words in the sense "backward" or "backup".
BACK_COMPOUNDS = {"backward", "backwards", "backup", "backend", "backpack",
                  "backyard", "backdrop", "backbone", "backlight", "backlash", "バック"}
# "Background", "behind", and other words for the rear or back of something.
