def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold().lstrip("_")
    if word.startswith("background") or word.startswith("behind"):
        return None, 0.9
    if word.startswith(("backward", "backwards")):
        return None, 1.15
