programs.sol:
"""Short e-plus-consonant spelling fragments give a negative response.

Bare pieces such as eb, ep, eg, ev, and Cyrillic еб/еп/ег/ев are strongest.
Preceding and trailing letters weaken them. Familiar complete words and code
abbreviations are exceptions. This token-local rule deliberately omits lexical
irregularities and context-dependent changes. The first matching sequence
is used; tokens outside these rules receive zero.
"""
READS = ()

LATIN = {
    'b': 1.85, 'c': .85, 'f': 1.45, 'g': 1.4, 'h': 1.2, 'j': 1.25,
    'k': 1.1, 'p': 1.45, 'q': .4, 'v': 1.45, 'w': 1., 'y': .6, 'z': 1.,
    'ch': .85, 'sh': 1., 'sc': .55, 'sp': .6, 'ph': 1.45,
    'ck': .5, 'ff': .85, 'gg': .6,
}
CYRILLIC = {
    'б': 1.5, 'в': 1.1, 'г': 1.3, 'д': .35, 'ж': 1.4, 'з': .8,
    'к': .7, 'п': 1.6, 'с': .4, 'х': 1., 'ц': .35, 'ч': .75, 'ш': .7,
}
COMPLETE = set('''
web new few key they sex deep keep seek week view check every even event
never ever left kept steps debt fresh speech def ref href prev spec grep
'''.split())

def spelling_value(text):
    word = text.strip().lstrip('._/-(<[')
    s = word.lower()
    if s in COMPLETE:
        return 0.0
    if s in {'reg', 'rec', 'sec', 'tech'}:
        return -.25
    if s in {'dev', 'dec', 'vec'}:
        return -.4
    for i in range(len(s) - 1):
        if s[i] == 'e':
            table = LATIN
        elif s[i] == 'е':
            table = CYRILLIC
        else:
            continue
        consonant = s[i+1:i+3] if s[i+1:i+3] in table else s[i+1]
        strength = table.get(consonant, 0.)
        if not strength:
            continue
        onset = (1., .7, .2, .06)[min(i, 3)]
        trailing = len(s) - i - 1 - len(consonant)
        if trailing:
            if i == 0:
                strength *= .5 ** min(trailing, 4)
            else:
                strength *= .2 / trailing
        if text[:1].isspace():
            onset *= .75 if i == 0 else .95
        if word.isupper():
            onset *= .85
        return -strength * onset
    return 0.0

def step(carry, prefix, upstream):
    return None, float(spelling_value(prefix.token_strings[-1]))

"""A partial detector for bounds, intervals, and spatial containment.

English 'within' and 'less' respond strongly. 'From' and 'between' are
stronger after measurement words, but weaker for origins and abstract
relationships. 'Than' follows the sense of its comparison word. A few
translated containment markers and related prepositions are also recognized.
Everything else is zero. Only the trailing 80 characters are remembered,
and that memory resets at document boundaries.
"""
import re

READS = ()


def nouns(text):
    roots = set(text.split())
    return roots | {word + 's' for word in roots}


COPULA = set('is are be being was were been'.split())
DISTANCE = nouns('distance') | {'closeness'}
UNITS = nouns('year month week day hour minute second period time age mile '
              'kilometer kilometre meter metre') | {'km', 'feet', 'inches'}
QUANTITY = nouns('number value integer prime degree count quantity score')
PARTS = nouns('line row element item character token byte page record')
RELATION = nouns('relationship relation interaction link association connection '
                 'correlation') | {'correspondence', 'interplay', 'synergy'}
ORIGIN = set('come comes came coming derived deriving arise arises arising '
             'made formed forming learn learned learning adapted'.split())
START = {'start', 'starts', 'starting'}
RANGE = {'range', 'ranges', 'ranging', 'ranged'}
SEPARATION = set('away apart different differ differs separated separate'.split())
SMALLER = set('greater lower smaller shorter bigger other fewer older younger'.split())
LARGER = set('higher larger longer faster slower'.split())
# Translations: Chinese within/inside/time limit, Russian less/inside,
# and Spanish inside. These are token-local approximations.
TRANSLATED = {
    '以内': 0.57, '内': 0.22, '年限': 0.50, '期内': 0.40,
    'менее': 0.38, 'внутри': 0.15, 'dentro': 0.26,
}
WEAK = {
    'inside': 0.20, 'outside': 0.18, 'beyond': 0.17,
    'among': 0.11, 'against': 0.105, 'below': 0.08,
    'around': -0.09, 'about': -0.04, 'almost': -0.06,
}


def response(word, previous, before):
    if word == 'within':
        if previous in COPULA | QUANTITY | UNITS:
            return 0.65
        if previous in {'not', 'fall', 'falls', 'falling'}:
            return 0.72
        if previous in {'signatures', 'arguments'}:
            return 0.57
        return 0.49
    if word == 'less':
        if previous == 'not':
            return 0.94
        if previous == 'no':
            return 0.59
        if previous in QUANTITY:
            return 0.70
        return 0.54 if previous in COPULA else 0.35
    if word == 'from':
        if previous in DISTANCE:
            return 0.79 if previous == 'distance' else 0.53
        if previous in UNITS:
            return 0.51
        if previous in START:
            return 0.48
        if previous in QUANTITY:
            return 0.42
        if previous in RANGE | SEPARATION | PARTS | COPULA:
            return 0.28
        return -0.10 if previous in ORIGIN else 0.085
    if word == 'between':
        if previous in DISTANCE | QUANTITY | UNITS:
            return 0.58
        if previous in COPULA:
            return 0.49
        return -0.07 if previous in RELATION else 0.25
    if word == 'than':
        if previous == 'less':
            if before in {'no', 'not'}:
                return 0.71
            return 0.53 if before in COPULA | QUANTITY else 0.39
        if previous in {'earlier', 'later'}:
            return 0.46
        if previous in SMALLER:
            return 0.23
        return 0.13 if previous in LARGER else 0.02
    if word == 'exceed':
        return 0.60 if previous == 'not' else 0.30
    if word == 'of' and previous in {'age', 'ages'}:
        return 0.40
    return TRANSLATED.get(word, WEAK.get(word, 0.0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    words = re.findall(r'[a-z]+', tail.lower())
    previous = words[-1] if words else ''
    before = words[-2] if len(words) > 1 else ''
    value = response(word, previous, before)
    if word == 'less' and not token[:1].isspace():
        value = 0.07  # Often the suffix in words such as 'harmless'.
    return (doc, (tail + token)[-80:]), float(value)

programs.haiku:
"""Range and bound words: the words that open a limit, an interval or a distance
("within", "less than", "between", "distance from", "exceed", "inside"), in English and
some other languages. Each fires on the word itself, most strongly when it sets a
numeric bound ("less" after "not", "from" after "distance"). Vague quantity words
("any", "much", "few", "around", "about") sit slightly below zero."""
READS = ()

BOUND_WORDS = {
    "within": 0.48, "less": 0.33, "between": 0.18, "exceed": 0.35, "beyond": 0.15,
    "inside": 0.19, "outside": 0.19, "among": 0.11, "from": 0.09, "than": 0.02,
    "以内": 0.58, "之内": 0.42, "内": 0.2, "不足": 0.28, "менее": 0.4, "dentro": 0.24,
    "부터": 0.23, "까지": 0.21,
    "any": -0.06, "much": -0.05, "few": -0.06, "around": -0.09, "about": -0.04,
}
MEASURES = {"distance", "months", "minutes", "year", "number", "period", "miles",
            "difference", "days", "years", "time", "hours", "range"}
COMPARATIVES = {"less", "greater", "smaller", "bigger", "lower", "higher", "other"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word == "from" and prev in MEASURES:
        return None, 0.45
    if word == "between" and prev in MEASURES:
        return None, 0.43
    if word == "less" and prev == "not":
        return None, 1.0
    if word == "than" and prev in COMPARATIVES:
        return None, 0.31
    if word == "of" and prev == "result":
        return None, -0.17
    if word == "of" and prev == "age":
