    if word in ("many", "much") and prev == "how":
        return None, -0.25
    return None, BOUND_WORDS.get(word, 0.0)

programs.sol:
"""A local detector of methods, alternatives, and ways to accomplish a task.

Evaluative modifiers ('best', 'effective') and alternative modifiers ('another',
'alternate') strengthen the response. Definite references are weaker. The
following to/of/for links the method to its purpose. A few literal translations
of method/way are also recognized. State resets at each new document.
"""
READS = ()

METHODS = frozenset('way ways method methods approach approaches technique '
                    'techniques strategy strategies'.split())
CHOICES = frozenset('choice choices option options alternative alternatives'.split())
ANSWERS = frozenset('answer answers solution solutions remedy remedies'.split())
OTHER_MEANS = frozenset('form forms means manner idea ideas plan plans treatment '
                       'treatments procedure procedures'.split())
NOUNS = METHODS | CHOICES | ANSWERS | OTHER_MEANS
STRONG = frozenset('best better easy easier easiest simple simpler simplest quick '
                  'quicker quickest fast faster fastest effective efficient '
                  'preferred optimal practical straightforward clever elegant'.split())
QUALIFIED = frozenset('good great excellent convenient suitable appropriate correct '
                     'right wrong incorrect valid accurate reasonable reliable ideal '
                     'possible potential feasible viable available promising safe '
                     'traditional conventional common standard classical popular'.split())
TECHNICAL = frozenset('numerical analytical scientific mathematical statistical '
                     'computational iterative recursive proposed recommended'.split())
DEFINITE = frozenset('the this that these those'.split())
POSSESSIVE = frozenset('my your his her its our their'.split())
SEARCH = frozenset('find finding found discover discovering discovered'.split())
TRANSLATED = frozenset('方法 的方法 方式 的方式 办法 的办法 途径 方案 做法 '
                      'способ метод подход вариант manera cách'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev = before = ''
        signal = 0.0
        capital = False
        first = True
    else:
        _, prev, before, signal, capital = carry
        first = False
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word in NOUNS:
        base, gain = .3, 1.5
        if word == 'way':
            base, gain = .5, 1.8
        elif word == 'ways':
            base, gain = .05, 1.4
        elif word in OTHER_MEANS:
            base, gain = .12, .8
        elif word in ANSWERS:
            base, gain = .05, 1.4
        strength = 0.0
        if prev in {'alternative', 'alternate'}:
            strength = 1.6
        elif prev == 'another':
            strength = 1.2
        elif prev in STRONG or prev.endswith('effective'):
            strength = 1.0
        elif prev in QUALIFIED:
            strength = .65
        elif prev in {'new', 'other', 'one'}:
            strength = .8
        elif prev in {'different', 'only'}:
            strength = .5
        elif prev in {'which', 'whichever', 'either'} or prev in TECHNICAL:
            strength = .3
        elif prev in SEARCH:
            strength = .5
        value = base + gain * strength
        if prev in DEFINITE:
            value = -.1 if word in ANSWERS | CHOICES else .1
        elif prev in POSSESSIVE:
            value = -.25 if word in ANSWERS | CHOICES else .1
        elif prev in {'a', 'an'}:
            value = .3
            if word in {'option', 'alternative', 'approach'}:
                value = .85
            elif word in {'method', 'methods'}:
                value = .55
            elif word == 'way':
                value = 1.7 if before in SEARCH else .85
                if before in {'in', 'such'}:
                    value = .1
        elif capital and prev in {'another', 'alternative', 'alternate', 'one'}:
            value += .6
        if word == 'way' and prev in {'under', 'half', 'long', 'by'}:
            value = -.6
        if word == 'ways' and prev in {'many', 'in'}:
            value = -.3
        if not (first or token.startswith((' ', '\n', '\t', '-'))):
            value *= .25
    elif word in {'to', 'of', 'for'}:
        relation = {'to': 0, 'of': 1, 'for': 2}[word]
        if prev in NOUNS:
            if prev in {'way', 'ways'}:
                values = (1.35, 1.1, .35)
            elif prev in {'method', 'methods'}:
                values = (.25, 1.0, .8)
            elif prev in {'approach', 'approaches'}:
                values = (1.2, .35, .5)
            elif prev in {'alternative', 'alternatives'}:
                values = (1.7, .9, .9)
            elif prev in ANSWERS:
                values = (1.15, .3, .85)
            elif prev in CHOICES:
                values = (.5, .2, .65)
            else:
                values = (.3, .3, .5)
            value = values[relation] + (.3, .5, .3)[relation] * signal
        elif prev == 'how' and word == 'to':
            value = .45
        elif prev in {'better', 'best', 'preferable'}:
            value = (.95, .3, .7)[relation]
        elif prev in {'possible', 'easier', 'safe', 'appropriate', 'helpful'}:
            value = (.65, .0, .4)[relation]
        elif prev in {'available', 'good', 'effective', 'suitable'}:
            value = (.4, .0, .3)[relation]
    elif word in TRANSLATED:
        value = .7
        context = before + prev
        if any(s in context for s in ('最好', '更好', '解决', '解決', '一种')):
            value = 2.1
        elif any(s in context for s in ('新', '有效', '正确', '其他', '哪种', '传统')):
            value = 1.5
    value = float(value)
    return (doc, word, prev, value, token.strip()[:1].isupper()), value

programs.luna:
"""Approximate the component's association with ways and methods.

It often fires on a way, approach, choice, or solution, especially when the
word is qualified ("another approach", "better way") or linked by "to".
These short lexical cues do not capture every contextual case.
"""
READS = ()

WAYS = {"way", "ways", "approach", "approaches"}
CHOICES = {"choice", "choices", "option", "options", "alternative", "alternatives"}
METHODS = {
    "method", "methods", "technique", "techniques", "strategy", "strategies",
    "practice", "practices", "solution", "solutions", "route", "routes",
    "procedure", "procedures", "algorithm", "algorithms", "means", "path", "paths",
    "plan", "plans", "idea",
}
QUALITIES = {
    "another", "better", "best", "good", "right", "easy", "easier", "new",
    "innovative", "clever", "popular", "appropriate", "flexible", "proven",
    "feasible", "ultimate",
}


def word(token):
    return token.strip().lower().strip(".,;:!?()[]{}\"'`*_-")


def step(carry, prefix, upstream):
    current = word(prefix.token_strings[-1])
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""

    value = 0.0
    if current in WAYS:
        value = 0.75
    elif current in CHOICES:
        value = 0.4
    elif current in METHODS:
        value = 0.4

    if current in WAYS | CHOICES | METHODS and previous in QUALITIES:
        value = 1.0
    elif current == "to" and previous in WAYS | {"solution", "answer"}:
        value = 1.2
    elif current == "to" and previous in {
