}
CHAT_MARKERS = {
    '<tool_response>': 0.26, '</tool_response>': 0.07,
    '<tool_call>': -0.14, '<|im_start|>': -0.066, '<|im_end|>': 0.03,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        previous, tail = carry[1:]
    token = prefix.token_strings[-1]
    spelling = token.strip()
    word = spelling.lower()
    spaced = token.startswith(' ')
    title = spelling.istitle()
    value = ACADEMIC_FORMS.get(word, CHINESE_ACADEMIC.get(word, -0.003))
    if word in SCHOLARLY_WORDS:
        value = 0.5
    elif word == 'academic':
        value = 2.35 if title else (2.9 if spaced else 2.7)
    elif word == 'acad' and not spaced:
        value = 0.52
    elif word == 'professor' and title and spaced:
        value = 2.95
    elif word == 'prof' and title:
        value = 2.0
    elif word in {'lecturer', 'semester', 'scholarly', '-reviewed'}:
        value = {'lecturer': 1.05, 'semester': 0.7,
                 'scholarly': 0.8, '-reviewed': 0.67}[word]
    elif word.lstrip('-') in {'lint', 'eslint'}:
        value = -0.4 - (0.35 if word.startswith('-') else 0.0)
    elif token in CHAT_MARKERS:
        value = CHAT_MARKERS[token]

    joined = tail + spelling if not spaced else spelling
    if not spaced and tail:
        end = joined.lower()
        if end.endswith('academic'):
            value = 2.8
        elif end.endswith('academics'):
            value = 1.5
        elif end.endswith(('academia', 'academies')):
            value = 0.8
        elif tail.lower().endswith('prof') and word == 'ess':
            value = 0.95 if spelling.isupper() else 1.6
        elif end.endswith('professors'):
            value = 2.2
        elif end.endswith('professor'):
            value = 2.75 if word == 'essor' else 0.95

    if previous.strip().lower() in {'professor', 'professors'}:
        if word in {'of', 'at', 'in'}:
            value = {'of': 1.25, 'at': 0.55, 'in': 0.4}[word]
            if previous.strip() == 'Professor':
                value *= 1.5
            elif previous.strip().lower() == 'professors':
                value *= 0.4
    elif previous.strip().lower() == 'prof' and spelling == '.':
        value = 1.05
    tail = joined[-24:] if spelling.isalpha() else ''
    return (doc, token, tail), float(value)

