"""Use small word cues for academic outcomes, plus a few enrollment cues.

The cues are sparse and noisy, so guesses stay small and most tokens get zero.
"""
import re

READS = ()

OUTCOMES = (
    "achiev", "grade", "proficien", "competenc", "prerequis",
    "усп", "обществен",
)
CJK_NEGATIVE = ("科目", "合格")
CONTEXT_TERMS = (
    "credit", "content", "subject", "study",
)
SCHOOL_CUES = (
    "academic", "student", "school", "learning", "course", "training",
    "graduat", "education", "college", "university", "curricul", "successful",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    document = prefix.document_ids[-1]
    history = "" if carry is None or carry[0] != document else carry[1]
    text = history + token
    if any(char.isalnum() for char in token):
        word = re.split(r"[^\w-]+", text)[-1]
    else:
        word = ""
    value = 0.0
    if word.endswith(CJK_NEGATIVE):
        value = -0.11
    elif any(word.startswith(root) for root in OUTCOMES):
        value = -0.11
    elif word.startswith("completion") and any(
        cue in history for cue in SCHOOL_CUES + ("outcome",)
    ):
        value = -0.11
    elif word.startswith("outcome") and any(
        cue in history for cue in SCHOOL_CUES + ("primary",)
    ):
        value = -0.11
    elif any(word.startswith(root) for root in CONTEXT_TERMS) and any(
        cue in history for cue in SCHOOL_CUES
    ):
        value = -0.11
    elif word.startswith("able") and any(
        cue in history for cue in ("student", "academic", "learning")
    ):
        value = -0.11
    elif word.startswith("curricul"):
        value = 0.05
    elif word.endswith(("报名", "竞赛")):
        value = 0.12
    elif word == "view" and "academic" in history:
