    return (document, text[-100:]), float(value)

"""A small text cue for likely noun heads: quantified or ordered words often
precede nouns. It marks these candidates weakly, rather than naming nouns."""
READS = ()

STRONG_CUES = {
    "each", "every", "another", "any", "one", "two", "first", "second",
    "third", "last", "single", "more",
}
WEAK_CUES = {"a", "an", "this"}
FUNCTION_WORDS = {
    "is", "are", "was", "were", "be", "been", "being", "do", "does", "did",
    "have", "has", "had", "can", "could", "will", "would", "shall", "should",
    "may", "might", "must", "not", "no", "and", "or", "but", "if", "as",
    "than", "then", "to", "of", "in", "on", "at", "by", "for", "from", "with",
    "into", "over", "under", "about", "up", "down", "out", "off", "very", "also",
    "just", "most", "less", "least", "only", "same", "own", "other", "like",
}
NOUN_ENDINGS = (
    "tion", "sion", "ment", "ness", "ity", "ance", "ence", "ship", "ism",
    "ist", "age", "ery", "ure", "hood", "dom",
)


def word(token):
    text = token.strip()
    while text and not text[0].isalpha() and not text[0].isdigit():
        text = text[1:]
    if not text:
        return ""
    return text.split()[0].strip(".,!?;:()[]{}\"'“”‘’").lower()


def step(carry, prefix, upstream):
    i = len(prefix) - 1
    current = word(prefix.token_strings[i])
    same_doc = i > 0 and prefix.document_ids[i] == prefix.document_ids[i - 1]
    previous = word(prefix.token_strings[i - 1]) if same_doc else ""
    if i > 1 and same_doc and prefix.document_ids[i - 1] == prefix.document_ids[i - 2]:
        before = word(prefix.token_strings[i - 2])
    else:
        before = ""

    candidate = (
        len(current) >= 3
        and current.isalpha()
        and current not in FUNCTION_WORDS
    )
    ordinal = previous == "th" and before.isdigit()
    superlative = previous.endswith("est") and (
        before.isdigit() or before.endswith("th")
    )
    strong_cue = (
        previous in STRONG_CUES
        or previous.isdigit()
        or ordinal
        or superlative
    )

    if candidate and strong_cue:
        value = -0.10
    elif candidate and previous in WEAK_CUES:
        value = -0.04
    elif candidate and current.endswith(NOUN_ENDINGS):
        value = -0.02
    else:
        value = 0.0
    return None, float(value)

