"""Predict selected form/example/standard spellings, not their meaning.

The large training peaks clustered around templates, norms, demonstrations,
and Chinese 范/範 and 模 expressions. Standalone 范/範 are particularly strong;
listed compounds have weaker responses. Capitalization and code separators
also affect the estimate. One-token Chinese continuations are handled in step.
Small responses to carriage returns and the chat-end marker are retained too;
all other tokens receive a near-zero background value.
"""
READS = ()


def lexical_value(token):
    if token == '\r':
        return -0.13
    if token == '<|im_end|>':
        return 0.06
    word = token.strip()
    lower = word.lower()
    bare = lower.lstrip('._-/(')
    if bare in ('template', 'templates'):
        if bare.endswith('s'):
            return -1.14 if token.startswith(' ') and word[:1].isupper() else -0.72
        if word.startswith('_'):
            return -0.68
        if word.startswith('/'):
            return -0.81
        if token.startswith(' ') or word[:1].isupper():
            return -1.25 if token.startswith(' ') and word[:1].isupper() else -1.14
        return -0.81
    if bare in ('norm', 'norms', 'norman'):
        return -0.74 if word[:1].isupper() or lower == 'norms' else -0.55
    if bare in ('demonstrate', 'demonstrates', 'demonstrating'):
        return -0.51
    if bare in ('demonstrated', 'demonstration', 'demonstrations'):
        return -0.33
    if bare in ('exemplary', 'paradigm'):
        return -0.44
    if bare in ('exempl', 'demo', 'demonstr'):
        return -0.30
    if bare in ('format', 'formats', 'fmt', 'sprintf', 'fprintf'):
        if token.startswith('\t'):
            return -0.48
        return -0.33 if token.startswith(' ') or word[:1].isupper() else -0.24
    if bare in ('sample', 'samples'):
        if word[:1].isupper():
            return -0.35
        return -0.21 if bare == 'sample' else -0.16
    if bare in ('range', 'ranges', 'scope', 'framework'):
        return -0.24
    if bare in ('plate', 'plates', 'board', 'manner'):
        return -0.18
    if word == '范':
        return -4.95
    if word == '範':
        return -4.45
    if word in ('范围', '範圍'):
        return -1.08
    if word in ('范围内', '範圍內'):
        return -0.45
    if word in ('规范', '規範'):
        return -2.45
    if word in ('规范化', '規範化'):
        return -1.6
    if word in ('示范', '示範'):
        return -3.3
    if word in ('示范区', '示範區'):
        return -0.50
    if word in ('范文', '範文', '师范', '師範', '典范', '典範', '模范', '模範'):
        return -3.0
    if word in ('师范大学', '師範大學'):
        return -1.3
    if word == '模板':
        return -1.4
    if word in ('模', '规模', '規模', '模样', '模樣'):
        return -0.74
    if word in ('格式', '观摩', '觀摩', '框架', '规格', '規格'):
        return -0.50
    if word in ('规', '規'):
        return -0.58
    if word in ('样本', '樣本', '样子', '樣子', '样', '樣', '演示', '展示'):
        return -0.30
    if word in ('板', '示'):
        return -0.27
    if word == '범':
        return -2.2
    if lower == 'норм':
        return -0.40
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, only_returns = '', True
    else:
        _, previous, only_returns = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    if '\ufffd' in token:
        # A byte fragment can finish a Chinese or Korean character.
        end = prefix.text_prefixes[-1][-1:]
        if end in ('范', '範', '模', '범'):
            word = end
            value = lexical_value(end)
            if end == '범':
                value *= 0.6
        else:
            value = lexical_value(token)
    else:
        value = lexical_value(token)
    if previous in ('范', '範'):
        # Complete a scope, paradigm, mathematical norm, or style expression.
        if word in ('围', '圍'):
            value = -0.9 if previous == '範' else -0.4
        elif word in ('式', '数', '數'):
            value = -1.3
        elif word in ('儿', '兒'):
            value = -1.8
    if token == '\r' and only_returns:
        value = -1.25
    only_returns = only_returns and bool(token) and not token.strip('\r')
    return (doc, word, only_returns), value

