programs.sol:
"""Approximate lexical uniqueness, with a separate accented-u response.

Training repeatedly shows large responses to 'unique', selected derivatives
and translations, and the letter ú. Related distinctness words and a few
other diacritics respond more weakly. Case, leading space, and fragment length
adjust the strengths. Unmatched tokens get a small background prediction.
Only completing a split UTF-8 acute-u letter uses preceding text.
"""
import unicodedata

READS = ()


def lexical_value(token):
    word = token.strip().lower()
    if word == 'unique':
        if not token.startswith(' '):
            return 1.9
        if token.strip().isupper():
            return 1.7
        return 2.2 if token.strip()[0].isupper() else 2.5
    if word.strip('._(') == 'unique':
        return 1.7
    if word == 'uniquely':
        return 2.2
    if word == 'uniqueness':
        return 1.3
    if word == 'uniqu':
        return 0.45
    # Romance and Russian stems meaning 'unique'.
    if word.startswith(('únic', 'уник')):
        return 1.4
    if word in {'distinct', 'distinctive', 'distinctly'}:
        return {'distinct': 0.75, 'distinctive': 0.6,
                'distinctly': 0.3}[word]
    if word in {'peculiar', 'unparalleled', 'sole', 'exclusive'}:
        return 0.8 if word == 'unparalleled' else 0.45
    if word in {'unprecedented', 'unified'}:
        return 0.7
    if word in {'novel', 'rare', 'diverse', 'alone'}:
        return 0.3
    # Chinese: alone, distinctive, one-of-a-kind, exclusive, and only-one.
    if word in {'独', '獨'}:
        return 2.9 if word == '独' else 2.5
    if word in {'独特', '独一无二', '的独特'}:
        return 2.2
    if word in {'独特的', '独有的'}:
        return 1.7
    if word in {'唯一', '唯一的'}:
        return 1.2
    if token.strip() == 'Ú':
        return 4.5
    if word.endswith('ú'):
        if len(word) == 1:
            return 3.7 if token.startswith(' ') else 3.9
        if len(word) == 2:
            return 2.1
        return 0.75 if len(word) == 3 else 0.05
    if word.startswith('ú'):
        return 0.65
    if word in {'ū', 'ű'}:
        return 0.65
    # Greek accented upsilon and the Thai long-u vowel mark.
    if word in {'ύ', 'ὺ', 'ῦ', 'ู'}:
        return 0.6
    # Masculine ordinal indicator.
    if word == 'º':
        return 1.0
    if len(word) == 1:
        base = unicodedata.normalize('NFD', word)
        if base[0] in 'oy' and '\u0301' in base:
            return 0.2
        if word == 'č':
            return 0.25
        if word == 'ľ':
            return 0.6
    return 0.002


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # Complete a split UTF-8 letter only when this token contains undecoded bytes.
    same_document = (prefix.position > 0 and
                     prefix.document_ids[-1] == prefix.document_ids[-2])
    if '\ufffd' in token and same_document:
        letter = prefix.text_prefixes[-1][-1:]
        if letter in 'úÚ':
            return None, 3.9 if letter == 'ú' else 4.7
    return None, float(lexical_value(token))

programs.haiku:
"""layers.0.mlp.down_proj:878 — a "unique / one-of-a-kind" and "ú" token detector.

The component's output is large on a few kinds of token, and near zero everywhere else:
  * the letter ú (U+00FA) when it is a whole token of its own ("ú", " ú"), as in Spanish,
    Portuguese, Slovak or Hungarian words split as "ú" + "nico" (único), "ú" + "loha", ...;
    short syllables ending in ú ("tú", "dú", "cú", "chú") fire more weakly;
  * the word "unique" and its forms (unique, Unique, uniquely, uniqueness, уникальный);
  * other words meaning "unique / sole / distinct" in other languages (唯一, 独特, 獨特,
    独, 獨, único, única) and a few English near-synonyms (distinct, sole, peculiar, ...).
Everything else is predicted as 0. The rule looks only at the newest token, so it is
stateless: the carry is unused.

Values are the typical activations on those tokens (about 3.8 for "ú", 2.3 for "unique",
2.0 for the synonyms, 1.5 for other short ú syllables). The token list is short on purpose:
it covers the largest effects and leaves the long tail of small activations unmodelled.
"""

# Words meaning "unique, one-of-a-kind, sole" (lowercased, stripped) beyond the "uniq" stem.
UNIQUE_WORDS = {
    "唯一", "独特", "獨特", "独", "獨", "único", "única",
    "sole", "distinct", "distinctive", "peculiar", "exclusive", "unparalleled",
}

READS = ()


def step(carry, prefix, upstream):
    # The newest token, as its decoded text (leading space and case removed).
    token = prefix.token_strings[-1].strip().lower()
    if token == "ú":
        value = 3.8
    elif "ú" in token and len(token) <= 3:
        value = 1.5  # short syllables such as "tú", "dú", "cú", "chú"
    elif "uniq" in token or "уник" in token:
        value = 2.3  # unique, uniquely, uniqueness, уникальный, ...
    elif token in UNIQUE_WORDS:
        value = 2.0
    else:
        value = 0.0
    return carry, float(value)

