"""A sparse lexical detector for affirmation and annotation/formatting cues.

'Indeed' is the strongest word cue; yes, in-fact phrasing and other
affirmation cues are weaker. Listed similarity/equivalence words and
fragments have negative responses. Independently, @-annotations, checkmarks,
Markdown image openers, thinking delimiters and long indentation are positive.
Levels summarize observed responses, not the cues' meaning. Unlisted tokens
predict zero; no general semantic analysis is attempted.
"""
READS = ()

# Assertion, comparison and emphasis vocabulary.
WORD_CUES = {
    'moreover': 0.54,
    'actually': 0.24,
    'certainly': 0.18,
    'definitely': 0.16,
    'likewise': -0.30,
    'equally': -0.94,
    'equivalent': -0.56,
    'equivalents': -0.85,
    'equivalence': -0.25,
    'equity': -0.82,
    'respectively': -0.33,
    'simultaneously': -0.35,
    'synonymous': -1.08,
    'analogous': -0.37,
    'truly': 0.25,
    'really': -0.15,
}
# Translations of affirmation, 'in fact', and 'similarly'.
TRANSLATIONS = {
    'именно': 0.70,
    'действительно': 1.04,
    '的确': 1.17,
    '确实': 0.96,
    '事实上': 0.50,
    '同样': -0.99,
    '同樣': -0.97,
    '確實': 0.96,
    '実際に': 0.78,
    '没错': 1.00,
    'tatsächlich': 1.20,
    'doch': 0.30,
}


def response(token, previous):
    word = token.strip()
    lower = word.lower()
    space = token.startswith(' ')
    if lower == 'indeed':
        if word.islower():
            return 3.93
        return 3.57 if space else 3.45
    if lower == 'yes':
        if word == 'Yes':
            return 1.05 if space else 1.19
        return 0.74 if space else 0.25
    if lower == 'similarly':
        return -0.95 if space and word == 'Similarly' else -0.66
    if lower == 'fact':
        return 0.65 if previous.strip().lower() == 'in' else 0.17
    # Incomplete equality/equivalence word pieces.
    if word in {'Equ', 'equ', 'Eq'}:
        if word == 'Eq':
            return -0.40
        if token == ' Equ':
            return -0.86
        return -0.40 if space else -0.53
    if lower == 'effet' and previous.strip().lower() == 'en':
        return 0.82
    if lower == 'instead':
        return 0.33 if word[0].isupper() else 0.17
    if lower in WORD_CUES:
        return WORD_CUES[lower]
    if lower in TRANSLATIONS:
        return TRANSLATIONS[lower]
    if word == '</think>':
        return 1.22
    if word == '<think>':
        return 0.37
    if word == '![':
        if '\n' in token:
            return 0.94
        return 2.68 if space else 3.06
    if word in {'#![', '<!['}:
        return 0.95
    if word == '.[':
        return 0.52
    if '@' in token:
        if '@@' in token:
            return 0.18 if space else 0.33
        if word.endswith('@'):
