programs.sol:
"""A lexical contrast between purity/absolute qualities and compound terms.

Purity spellings give strong negative responses; idealness, rawness, exclusivity
and completeness give weaker ones. Positive responses occur on the heads of
listed technical compounds and in typed method declarations. This is a lexical
approximation, not a general noun/adjective classifier. Other tokens give zero.
Only two previous spellings are remembered, within the current document.
"""
READS = ()

QUALITIES = (
    (-2.5, {'purely'}),
    (-1.4, {'purity'}),
    (-1.55, {'raw'}),
    (-1.15, {'perfect', 'solely'}),
    (-1.0, {'absolute', 'plain', 'pristine'}),
    (-0.75, {'bare', 'mere', 'predominantly', 'perfectly'}),
    (-0.6, {'strictly', 'exclusively', 'sheer'}),
    (-0.5, {'absolutely', 'crude'}),
    (-0.44, {'whole', 'entire', 'truly', 'strict', 'rough'}),
    (-0.33, {'full', 'actual', 'straight', 'flat', 'solo', 'genuine'}),
    (-0.26, {
        'constant', 'linear', 'dry', 'liquid', 'fully', 'entirely',
        'mostly', 'primarily', 'uniform', 'alone', 'classic', 'classical',
    }),
    (-0.15, {'true', 'real', 'natural', 'regular', 'direct', 'prime', 'exact'}),
)
QUALITY_WORDS = {w: v for v, words in QUALITIES for w in words}
# Purity, rawness, holiness and absoluteness counterparts in other scripts.
QUALITY_MORPHEMES = {
    '纯': -5.15, '純': -3.95, '纯粹': -3.05, '纯净': -2.3,
    '单纯': -1.75, '单纯的': -1.55, '순': -1.1,
    '圣': -0.5, '聖': -0.5, '绝对': -0.8, '絕對': -0.7, '原始': -0.8,
}

# Established compounds; the response is emitted on the head, not the modifier.
COMPOUNDS = (
    (5.3, {'finite element'}),
    (2.7, {'linked list', 'linked lists', 'finite difference'}),
    (2.0, {'fixed point', 'finite line'}),
    (1.7, {'random variable', 'random variables'}),
    (1.4, {
        'financial statement', 'financial statements', 'fatty acid',
        'fatty acids', 'virtual machine', 'virtual machines', 'decision tree',
        'frequently asked questions', 'protected area', 'protected areas',
    }),
    (1.0, {
        'linear algebra', 'linear combination', 'regular expression',
        'raw material', 'raw materials', 'floating point', 'turning point',
        'private sector', 'private property', 'genetic material', 'meta object',
    }),
    (0.8, {
        'straight line', 'straight lines', 'black hole', 'black holes',
        'complex number', 'mixed numbers', 'null hypothesis',
        'intellectual property', 'differential equation', 'differential equations',
        'directed graph', 'acyclic graph', 'matrix element', 'matrix elements',
        'binary tree', 'decision making', 'black smith',
    }),
    (0.6, {
        'amino acid', 'amino acids', 'operating system', 'operating systems',
        'critical point', 'tangent line', 'random number', 'chemical element',
        'delay line', 'delay lines', 'real estate', 'united kingdom',
    }),
)
TERMS = {term: v for v, terms in COMPOUNDS for term in terms}
METHOD_MODIFIERS = {
    'private': 3.3, 'protected': 2.8, 'static': 2.15, 'public': 1.65,
    'abstract': 1.5, 'override': 1.5, 'virtual': 1.15, 'inline': 1.2,
}
VISIBILITY = {'private', 'protected', 'public', 'static', 'final'}
TYPES = {'string', 'int', 'boolean', 'bool', 'double', 'long', 'float'}


def spelling(token):
    return token.strip().strip('._:-()<>').lower()


def response(token, previous, earlier):
    word = spelling(token)
    if token.strip() in QUALITY_MORPHEMES:
        return QUALITY_MORPHEMES[token.strip()]
    if word == 'pure':
        if token.strip()[:1].isupper():
            return -3.4
        return -4.05 if token[:1].isspace() else -2.65
    if word == 'holy':
        return -0.8 if token.strip()[:1].isupper() else -0.27
    if word in QUALITY_WORDS:
        value = QUALITY_WORDS[word]
        if token.strip()[:1].isupper():
            value *= 0.8
        if not token[:1].isspace():
            value *= 0.75
        return value
    if word == 'void':
        if previous in {'async', 'synchronized'}:
            return 3.6 if earlier == 'private' else 1.6
        return METHOD_MODIFIERS.get(previous, 0.35)
    if word == 'sub':
        return {'private': 2.9, 'public': 1.4}.get(previous, 0.0)
    if word == 'function':
        return {'private': 1.7, 'protected': 1.1,
                'public': 0.8, 'static': 0.78}.get(previous, 0.0)
    if word in TYPES and previous in VISIBILITY:
        value = 0.7 if previous != 'final' else 0.5
        if word in {'double', 'long', 'float'}:
            value *= 0.5
        if word == 'string' and previous == 'private':
            value = 1.1
        return value
    if word == 'final' and previous in VISIBILITY:
        return 0.9 if previous == 'private' else 0.62
    return TERMS.get(previous + ' ' + word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, earlier = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    # A token may finish a Unicode character while decoding alone to U+FFFD.
    if token and set(token) == {'\ufffd'}:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in QUALITY_MORPHEMES:
            token = completed
    value = response(token, previous, earlier)
    word = spelling(token)
    if word == 'asked' and previous == 'frequently':
        word = 'frequently asked'
    return (doc, word, previous), float(value)

