"""Layer-0 MLP down_proj component 882.

What it does, in words:
  * NEGATIVE on the word "pure" in any sense (pure, purely, purity; Chinese/Japanese 纯, 純).
    This is the strongest, most reliable effect.
  * Mildly NEGATIVE on absolute or unqualified modifiers: perfect, absolute, raw, solely,
    plain (about -1), and weaker on mere, bare, whole, entire, full (about -0.5).
  * POSITIVE on the head word that completes a fixed technical term: "finite element",
    "finite line", "finite difference", "linked list", "fixed point", "fatty acid",
    "amino acid", "straight line" (the modifier is the word just before).
  * POSITIVE on the type or return keyword in a method declaration after an access
    modifier: "void" (about +2), and function / int / String / Object / boolean (about +0.8).
Every other token is predicted as 0. The rule reads only the current word and the word before
it, and only inside the same document.
"""

READS = ()

PURE_WORDS = {"pure", "purely", "purity", "purest", "纯", "純"}
ABSOLUTE_WORDS = {"perfect", "perfectly", "absolute", "raw", "solely", "plain"}
WEAK_WORDS = {"mere", "bare", "whole", "entire", "full", "actual"}
ACCESS = {"public", "private", "protected", "static", "virtual"}
TYPE_WORDS = {"function", "int", "String", "Object", "boolean", "final"}
TERMS = {
    ("finite", "element"): 4.0, ("finite", "line"): 2.0, ("finite", "difference"): 3.0,
    ("linked", "list"): 2.5, ("linked", "lists"): 2.5, ("fixed", "point"): 2.0,
    ("fatty", "acid"): 1.5, ("amino", "acid"): 1.5, ("straight", "line"): 0.8,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
    if word.lower().startswith("pure") or word in PURE_WORDS:
        value = -4.0
    elif word in ABSOLUTE_WORDS:
        value = -1.2
    elif word in WEAK_WORDS:
        value = -0.5
    elif (prev.lower(), word.lower()) in TERMS:
        value = TERMS[(prev.lower(), word.lower())]
    elif prev in ACCESS and word == "void":
        value = 2.0
    elif prev in ACCESS and word in TYPE_WORDS:
        value = 0.8
    else:
        value = 0.0
    return carry, value

