DOMAIN = {
    'field': -.5, 'fields': -.5, 'area': -.25, 'areas': -.5,
    'subject': -.75, 'subjects': -.8, 'topic': -.65, 'topics': -.75,
    'aspect': -.65, 'aspects': -.7, 'sector': -.55, 'sectors': -.85,
    'branch': -.5, 'branches': -.7, 'domain': -.2, 'domains': -.35,
    'theme': -.25, 'themes': -.25, 'matter': -.18, 'matters': -.25,
    'realm': -.9, 'realms': -1.2, 'sphere': -.2, 'spheres': -.3,
    'discipline': -1.4, 'disciplines': -2.1, 'discipl': -.9,
    'disciplinary': -1., 'interdisciplinary': -1.6,
    'intersection': -.8, 'intersections': -.65,
    'intersect': -.55, 'intersects': -.55,
    'overlap': -.4, 'overlaps': -.45, 'overlapping': -.5,
    'profession': -.35, 'professions': -.65,
    'science': -.3, 'sciences': -.8, 'scope': -.1,
    'industry': -.17, 'industries': -.3, 'genre': -.3,
