    '学科': -1.2, '學科': -1.2, '科目': -.4, '科': -.25,
    '主题': -.4, '主題': -.4, '交叉': -.75, '野': -.2,
    'sujet': -.5, 'sujets': -.65, 'domaine': -.4,
    'campo': -.4, 'campos': -.5, 'área': -.65, 'áreas': -.65,
    'tema': -.3, 'temas': -.3, 'thema': -.35, 'bereich': -.85,
    'раздел': -.55, 'наук': -.55, 'сфере': -.9, 'тем': -.25,
    'области': -.3, 'métier': -.8, 'مجال': -.7,
