"""A mixed code-and-path syntax response, approximated from visible text.

Empty calls, attached opening delimiters, double underscores, and scope
separators are the main positive triggers. Attached closing punctuation
changes call strength. Dotted names depend on their length, casing and
whether the line is an import. Recognizable Python, JavaScript, Java GUI,
Spring, SQL, and license idioms have additional rules, as do .com domains.
Typing judgments and conversation boundaries have separate signed responses.
Other tokens default to zero: this is not a full lexical reconstruction.

Only the preceding token and a bounded current line are remembered; both
reset when the document changes. Coefficients summarize training examples.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line = '', ''
    else:
        _, previous, line = carry
    s = prefix.token_strings[-1]
    bare = s.lstrip()
