    if call:
        angles, tail = call.groups()
        value = (0.97 - 0.22 * bool(angles) - 0.34 * (bare != s)
                 - 0.20 * tail.count(')')
                 - 0.07 * (';' in tail) - 0.12 * (',' in tail)
                 - 0.12 * tail.count('\n') - 0.32 * ('{' in tail)
                 + 0.08 * ('.' in tail) + 0.10 * ('`' in tail)
                 + 0.40 * ('->' in tail or '=>' in tail))
        value = max(0.0, value)
