        value = 1.8
    elif s == '(' and previous.strip() in ('sqrt', 'left', 'right'):
        value = 0.15
    elif s == '(':
        word = re.search(r'[A-Za-z_][A-Za-z_0-9]*$', previous)
        value = 0.05 if not word else 0.17 if len(word[0]) == 1 else 0.53
    elif bare.startswith(('("', "('")) and bare != s:
        value = 0.35
    elif s.startswith('('):
        c = s[1:2]
        if c in ('"', "'", '`'):
            value = 0.70
        elif c in ('[', '{'):
            value = 0.73
        elif c == '|' and s[2:3] != '|':
            value = 0.95
        elif c == '\\':
            value = 0.51 if '"' in s else 0.26
        elif c and not c.isalpha() and c != '_':
            value = 0.44
        else:
            value = 0.05
    # Package paths and crawler entry points.
    elif s == '-eslint' and previous.endswith('typescript'):
        value = 1.25
    elif s == '/parser' and previous == '-eslint':
        value = 2.0
    elif s in ('_urls', '_requests') and previous.endswith('start'):
        value = 1.75 if s == '_urls' else 1.0
    # Underscore separators occur in identifiers and repository paths.
    elif s == '__':
        value = 1.00
    elif s == '_':
        value = 0.29
    elif bare == '__' or s in ('/__', '.__'):
        value = 0.52
    elif s == '_modules' and previous.endswith('node'):
        value = 0.90
    elif s == '_INCREMENT' and previous == ' AUTO':
        value = 1.6
    elif s.startswith('_') and len(s) > 1:
        value = 0.06
    elif bare == '::':
        value = 0.48 if bare == s else 0.67
    elif s.startswith('.') and s[1:2].isalpha():
        word = s[1:]
        compound = sum(c.isupper() for c in word) >= 2
        long_name = len(word) >= 12
        value = (0.01 + 0.10 * (len(word) >= 7) + 0.06 * long_name
                 + 0.24 * compound + 0.27 * (long_name and compound))
        if re.match(r'\s*(import|using|package)\b', line):
            value += 0.20 + 0.15 * word.istitle() + 0.38 * compound
        # Java GUI layout enums and Spring annotation namespaces.
        if s == '.GroupLayout' and previous == '.swing':
            value = 1.9
        elif s == '.Alignment' and previous == '.GroupLayout':
            value = 4.8
        elif s == '.ComponentPlacement' and previous == '.LayoutStyle':
            value = 4.0
        elif s in ('.LEADING', '.TRAILING') and previous == '.Alignment':
            value = 2.5
        elif s == '.swing' and previous.endswith('javax'):
            value = 1.45
        elif s in ('.annotation', '.stereotype') and 'springframework' in line:
            value = 3.2
        elif s == '.log' and previous.endswith('console'):
            value = 0.82
        elif s in ('.stringify', '.dumps'):
            value = 2.0
        elif s == '.com':
            social_or_mail = previous.endswith(
                ('github', 'ithub', 'twitter', 'gmail', 'qq'))
            value = 0.80 if social_or_mail else 0.20
    elif s == 'self' and previous.endswith('__('):
        value = 1.45 if line.endswith('init__(') else 0.28
    elif s == 'init' and previous.endswith('.__'):
        value = 1.10
    elif s == 'init' and previous.endswith('/__'):
        value = 0.67
    elif s == ' License':
        value = 2.5 if 'limitations under the' in line else 0.55
    elif s == ' CHARSET':
        value = 3.0
    elif s == ' DEFAULT':
        value = 0.70
    elif s == ' NULL' and previous == ' NOT':
        value = 0.50
    elif s == ' INTO' and previous.strip().upper() == 'INSERT':
        value = 1.0
    elif s == ' Type' and previous.rstrip().endswith(':'):
        value = -0.85
    elif s == '</tool_call>':
        value = 0.37
    elif s == '<|im_end|>':
        value = -0.10
    elif s.startswith('\\') and s[1:2].isupper() and len(s) > 3:
        value = 0.40

    line = (line + s).split('\n')[-1][-240:]
    return (doc, s, line), float(value)

"""History, heritage, and temporal reference, mostly as a lexical signal.

Selected history words, including Chinese/Japanese 史, are strongest. Words
about antiquity, origins, remembering, and time are weaker. History in code
(e.g. _history) also counts. Unlisted tokens predict zero. A small carry
recognizes split history words and the unusually strong 'of' in 'history of'; it resets at documents.
"""
import re

READS = ()

HISTORY = {
    'history': 6.95, 'histories': 6.5,
    'historical': 7.7, 'historically': 5.8,
    'historic': 5.6, 'historian': 5.1, 'historians': 5.2,
    'histor': 4.8, 'hist': 2.8,
    '史': 7.0, '历史': 8.3, '歷史': 7.5,
}

ANTIQUITY = {
    'ancient', 'antique', 'vintage', 'classic', 'medieval', 'legendary',
    'chronological', 'timeless',
}
HERITAGE = {
    'heritage', 'tradition', 'traditions', 'timeline', 'memories',
    'origins', 'ancestry', 'legacy', 'biography',
}
PAST_REFERENCE = {
    'old', 'oldest', 'former', 'formerly', 'early', 'earliest', 'recent',
    'previously', 'yesterday', 'origin', 'originally', 'traditional',
    'anniversary', 'classical', 'famous', 'ancestors', 'iconic',
}
MEMORY_AND_NARRATIVE = {
    'memory', 'remember', 'remembered', 'recall', 'forgotten', 'memorial',
    'museum', 'culture', 'cultural', 'story', 'stories', 'record', 'records',
    'experience', 'experiences', 'life', 'career', 'original', 'background',
    'today', 'back', 'older', 'earlier', 'ago', 'recently', 'century',
    'prior', 'calendar', 'childhood', 'deprecated',
    'decade', 'decades', 'generations', 'modern', 'contemporary',
    'log', 'logs', 'events', 'evolution', 'veteran', 'dating',
}
TIME = {
    'time', 'times', 'years', 'once', 'always', 'ever', 'never', 'since',
    'period', 'later', 'existing', 'current',
}

# Translations of history, antiquity, heritage, and temporal reference.
ASIAN_ANTIQUITY = {
    '古', '古代', '古镇', '历', '歷', '过去', '過去', '经历', '昔', '以往',
}
ASIAN_HERITAGE = {'旧', '舊', '传统', '傳統', '经典', '經典', '传奇', '傳奇'}
ASIAN_PAST = {'以前', '曾经', '曾經', '当年', '當年', '去年', '回顾', '回顧'}
ASIAN_MEMORY = {'文化', '经验', '經驗', '原', '传', '傳', '未来', '未來'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().strip('_-.():/').lower()

    if word in HISTORY:
        value = HISTORY[word]
        if token.startswith('_') and word == 'history':
            value *= 0.82
    elif '历史' in word or '歷史' in word:
        value = 7.8 if word in {'的历史', '的歷史', '历史上', '歷史上'} else 4.8
    elif word in {'史上', '史料', '党史'}:
        value = 6.5
    elif word.startswith(('истор', 'histó')) or word == '역사':
        value = 3.8
    elif word in {'histoire', 'storia', 'geschichte', 'historia'}:
        value = 2.3
    elif word in ASIAN_ANTIQUITY:
        value = 2.8
    elif word in ASIAN_HERITAGE:
        value = 2.1
    elif word in ASIAN_PAST:
        value = 1.5
    elif word in ASIAN_MEMORY:
        value = 1.0
    elif word == 'nostalgic':
        value = 3.1
    elif word == 'past':
        value = 3.2
    elif word == 'previous':
        value = 1.55
    elif word == 'future':
        value = 1.3
    elif word == 'ancient' or word.startswith('древ'):
        value = 2.4
    elif word in ANTIQUITY:
        value = 2.0
    elif word in HERITAGE:
        value = 1.6
    elif word in {'early', 'earliest', 'centuries'}:
        value = 1.4
    elif word in PAST_REFERENCE:
        value = 0.65 if token == 'old' else 1.2
    elif word in {'log', 'logs', 'events'}:
        value = 0.45
    elif word in MEMORY_AND_NARRATIVE:
        value = 0.75
    elif word == 'year':
        value = 0.25
    elif word in TIME or word in {'年', '记', '記'}:
        value = 0.4
    else:
        value = 0.0

    # Suffix tokens of a history word get a smaller, continuing response.
    if token and token[0].isalpha() and previous in {'hist', 'histor'}:
        joined = previous + word
        if joined in HISTORY:
            value = 5.7 if joined.startswith('historical') else 3.7
    elif token and token[0].isalpha() and previous == 'h':
        joined = previous + word
        if joined == 'historical':
            value = 5.7
        elif joined == 'history':
            value = 3.2
    else:
        joined = word
    if word == 'of':
        if previous == 'history':
            value = 2.95
        elif previous == 'histories':
            value = 2.1
        elif previous in {'historian', 'historians'}:
            value = 1.3
        elif previous in HERITAGE or previous in {'origin', 'anniversary'}:
            value = 0.9
        elif previous in {'story', 'memory', 'museum', 'future', 'records'}:
            value = 0.6

    tail = re.search(r'[a-z]+$', joined)
    return (doc, tail.group() if tail else word), value

programs.haiku:
"""Words about history and the past.

A layer-0 MLP unit that reads the current token. It is near zero almost everywhere
and fires on words that talk about history and the past, in four strengths:

  * strong (about 6): history and its relatives (historical, historic, historian,
    "_history"), and the same word in Chinese, Russian and German
    (史, 历史, 歷史, истории, Geschichte);
  * past (about 3 for "past" and "ancient"-like words, 1.4 for other words of
    former times): past, previous, previously, former, early, old, ancient,
    classical, future, 古, 过去, 以前, 昔, 旧, 传统, 经典;
  * weak (about 0.6): related time and record words: origin, memory, heritage,
    recent, ago, years, time, life, record, museum, ever, since, back, today;
  * "of" right after a history word ("history of", about 2.7): the unit carries
    the history meaning on to the next token.

Everything else predicts 0. The values are rounded average activations of each
group on training text.
"""

READS = ()

HISTORY_STEMS = ("histor", "hist", "史", "历史", "歷史", "истор", "geschichte")

PAST_WORDS = {
    "previous", "previously", "former", "formerly", "early", "earlier",
    "earliest", "old", "older", "oldest", "ancient", "classic", "classical",
    "traditional", "tradition", "future", "古", "过去", "過去", "以前", "曾经", "昔",
    "歷", "旧", "傳統", "传统", "经典", "經典", "历年", "前辈",
    "originally", "original", "antique", "vintage", "medieval", "legend",
    "legends", "ancestors", "timeline",
}

WEAK_WORDS = {
    "origin", "origins", "memory", "memories", "heritage", "recent", "recently",
    "ago", "yesterday", "anniversary", "decades", "generations", "years", "time",
    "life", "record", "records", "museum", "archives", "ever", "since", "back",
    "today", "never", "story", "experience", "experiences",
}


def _word(s):
    # lower-case word with the leading space and any underscores removed
    return s.strip().lower().lstrip("_")


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    prev = _word(prefix.token_strings[-2]) if len(prefix) > 1 else ""
    if word.startswith(HISTORY_STEMS):
        value = 6.0
    elif word in {"past", "古", "ancient", "classic", "classical", "過去", "经典"}:
        value = 3.0
    elif word in PAST_WORDS:
        value = 1.4
    elif word in WEAK_WORDS:
        value = 0.6
    elif word == "of" and prev.startswith(HISTORY_STEMS):
        value = 2.7
    else:
        value = 0.0
    return carry, value

