"""Estimate an occasional noun-like response in a possessive phrase.

The positive examples often put a noun after a possessive word ("their
condition", "his head", "my time").  This uses that grammar and common noun
and adjective word endings; it does not try to recognize every word.
"""
import re

READS = ()

POSSESSIVE = re.compile(r"(?:\b(?:my|your|his|her|its|our|their)|\b[\w’'-]+(?:'s|’s))\s*$", re.I)
NOUN_ENDINGS = (
    "tion", "sion", "ment", "ity", "ness", "ance", "ence", "ship",
    "hood", "ism", "ist", "ure", "age", "ery", "or", "ity",
)
ADJECTIVE_ENDINGS = (
    "ed", "ous", "ful", "less", "able", "ible", "ive", "al", "ic",
    "ary", "est",
)
COMMON_ADJECTIVES = {
    "best", "main", "total", "specific", "invested", "largest",
}


def step(carry, prefix, upstream):
    previous, old_doc = ("", None) if carry is None else carry
    doc = prefix.document_ids[-1]
    if old_doc is not None and doc != old_doc:
        previous = ""

    token = prefix.token_strings[-1]
    stripped = token.strip()
    response = 0.0

    if not stripped and POSSESSIVE.search(previous):
        response = -0.65
    elif stripped and any(ch.isalpha() for ch in stripped):
        if POSSESSIVE.search(previous):
            word = stripped.casefold().strip(".,;:!?()[]{}\"'“”’")
            if word in COMMON_ADJECTIVES or word.endswith(ADJECTIVE_ENDINGS):
                response = -0.55
            elif word.endswith(NOUN_ENDINGS) or word.endswith("s"):
                response = 0.65

    tail = (previous + token)[-80:]
    return (tail, doc), float(response)

programs.sol:
"""Approximate format-start responses plus small lexical/grammatical biases.

The rare strong harvested responses were document-opening empty comments,
HTML's <! opener, and documents beginning with repeated carriage returns.
Those are handled separately. Elsewhere, this uses training averages for
familiar word classes, protocol delimiters, scripts, and a few local
English grammar patterns. Most token-specific variation remains unexplained.
"""
READS = ()

DELIMITERS = {
    '<think>': 0.146, '</think>': -0.024,
    '<tool_call>': -0.044, '</tool_call>': -0.088,
}
OPENING_COMMENTS = {
    '//\n': 0.563, '//\r\n': 0.476,
    '#\n': 0.624, '#\r\n': 0.394,
}
REASONING = frozenset('''
problem problems solution solutions answer answers question questions
example examples idea ideas choice choices
'''.split())
WORK = frozenset('''
work study studies program programs performance production control
'''.split())
ACCURACY = frozenset('''
correct incorrect accurate inaccurate precise correctly incorrectly
accurately precisely
'''.split())
REPETITION = frozenset('again back repeated repeatedly'.split())
PERCEPTION = frozenset('see sees find finds'.split())
GIVING = frozenset('give gives gave'.split())
EQUALITY = frozenset('same equal'.split())
QUANTIFIERS = frozenset('some any several certain'.split())
SIZE = frozenset('small short large great'.split())
COMPARATIVE_SIZE = frozenset('smaller shorter larger bigger lower'.split())
CAUSE = frozenset('because therefore thus hence'.split())
WORD_CLASSES = (
    (REASONING, -0.052), (WORK, -0.052), (ACCURACY, -0.050),
    (REPETITION, -0.052), (PERCEPTION, -0.056), (GIVING, -0.092),
    (EQUALITY, 0.062), (QUANTIFIERS, 0.030), (SIZE, 0.030),
    (COMPARATIVE_SIZE, -0.044), (CAUSE, 0.035),
)
ARTICLES = frozenset('a an the'.split())
BE = frozenset('be am is are was were been being'.split())
QUESTIONS = frozenset('how why when where'.split())
RESTRICTIONS = frozenset('only just solely merely alone'.split())
NEGATIONS = frozenset('no not never non without'.split())
DEMONSTRATIVES = frozenset('this that these those you your yours'.split())
DEGREES = frozenset('''
many much more most few fewer less least very so quite rather
'''.split())


def background(token, word):
    if token in DELIMITERS:
        return DELIMITERS[token]
    if word in ("'s", '’s'):
        return 0.032
    if word == 'there':
        return -0.075
    if word == 'too':
        return -0.130
    if word in ('no', 'non'):
        return 0.037
    for words, value in WORD_CLASSES:
        if word in words:
            return value
    if word.isdigit():
        return -0.009 if word == '9' else 0.002
    return 0.001


def punctuation(token):
    return bool(token.strip()) and not any(c.isalnum() for c in token)


def local_adjustment(token, word, previous):
    prev_word = previous.strip().lower()
    change = 0.0
    if word.isascii() and word.isalpha():
        if prev_word in QUESTIONS:
            change -= 0.026
        elif prev_word in RESTRICTIONS:
            change -= 0.018
        elif prev_word in NEGATIONS:
            change -= 0.012
        if word in ARTICLES and prev_word in BE:
            change += 0.021
        if word in REASONING and prev_word in ARTICLES:
            change -= 0.023
        if word in DEGREES and prev_word in ARTICLES:
            change += 0.034
        if word in DEMONSTRATIVES and punctuation(previous):
            change += 0.021
        if token.strip().isupper() and previous.strip().isupper():
            change -= 0.009
    elif any('\u3040' <= c <= '\u309f' for c in token):
        change += 0.014  # Hiragana.
    elif any('\u4e00' <= c <= '\u9fff' for c in token):
        change += 0.005  # Han characters.
    elif any('\u0400' <= c <= '\u04ff' for c in token):
        change += 0.004  # Cyrillic.
    elif punctuation(token) and punctuation(previous):
        change -= 0.005
    return change


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    only_returns = first or carry[1]
    word = token.strip().lower()
    value = background(token, word)
    if not first and not token.startswith('<'):
        value += local_adjustment(token, word, carry[2])
    if token == '\r':
        value = 0.386 if only_returns else -0.036
    elif first:
        if token in OPENING_COMMENTS:
            value = OPENING_COMMENTS[token]
        elif token == '<!':
            value = 0.673
        elif token == '<|im_start|>':
            value = 0.060
    return (doc, only_returns and token == '\r', token), value

programs.haiku:
"""Mental-state verbs after a person.

The component fires on verbs and adjectives of thinking, believing, hoping, knowing, feeling
and expecting, most of all right after "I": "I think" (strongest), "I believe", "I hope",
"I know", "I'm sure", "I feel", "it seems". Other people as subject ("you think", "we
believe", "I don't think") give about half as much. Without a subject before it ("so I
think", "make sure") it gives a third as much, and after "to" ("to think") very little.
Weaker still on the word after such a verb ("think that", "seems like").
Ordinary action verbs after a person ("I do", "I get", "I go") are slightly negative.
"""

READS = ()

# how strongly each word signals a belief, feeling or expectation (activation after "I")
STANCE = {
    "think": 4.9, "hope": 4.3, "believe": 4.2, "doubt": 4.2, "thought": 3.8, "guess": 3.8,
    "suspect": 3.3, "believes": 2.9, "thinks": 2.9, "hoping": 2.8, "afraid": 2.6,
    "thinking": 2.5, "sure": 2.4, "feel": 2.3, "glad": 2.2, "confident": 2.2, "trust": 2.1,
    "expect": 1.8, "aware": 1.8, "felt": 1.7, "feels": 1.7, "know": 1.6, "agree": 1.6,
    "fear": 1.6, "wonder": 1.5, "knew": 1.5, "hate": 1.5, "knows": 1.4, "imagine": 1.3,
    "expecting": 1.3, "pleased": 1.3, "seems": 1.3, "appreciate": 1.2, "wish": 1.2,
    "disagree": 1.2, "worried": 1.2, "like": 1.1, "happy": 1.1, "love": 1.0, "seemed": 1.0,
    "suggest": 0.9, "want": 0.7, "wanted": 0.8, "wants": 0.9, "realize": 0.9, "suppose": 0.9,
    "assume": 0.7, "understand": 0.8, "confidence": 1.0, "thoughts": 1.0, "opinion": 0.8,
    "looks": 0.6, "sounds": 0.6, "appears": 0.6, "certain": 0.6, "expects": 0.7,
}
I_SUBJECT = {"i", "m", "’m", "am"}   # "I", and "I'm" / "I am" with the "I" before it
WEAK = {"would": 0.4, "need": 0.3}   # weakly positive after a person
ACTION = {"do", "did", "get", "go", "tell", "ask", "use", "start", "learn", "keep", "make"}
OTHER_PEOPLE = {"you", "we", "they", "he", "she", "me", "not", "n't", "'m", "’m", "'t", "’t", "am"}
SEEM = {"seems", "seem", "seemed", "looks", "look", "looked", "sounds", "sound", "feel", "felt", "feels"}
FOLLOWERS = {"that", "this", "the", "it", "you"}   # what often comes right after such a verb

def clean(token):
    """A token as a lowercase word, without its leading space or quote mark."""
    return token.strip().lower().lstrip('"“”\'')

def step(carry, prefix, upstream):
    strings = prefix.token_strings
    word = clean(strings[-1])
    prev = clean(strings[-2]) if len(strings) > 1 else ""
    if word == "like" and prev in SEEM:
        return None, 2.2
    if word in STANCE:
        if prev in I_SUBJECT:
            return None, 1.2 * STANCE[word]
        if prev in OTHER_PEOPLE:
            return None, 0.65 * STANCE[word]
        if prev == "to":
            return None, 0.15 * STANCE[word]
        return None, 0.35 * STANCE[word]
    if prev in I_SUBJECT or prev in OTHER_PEOPLE:
        if word in WEAK:
            return None, WEAK[word]
        if word in ACTION:
            return None, -0.4
        return None, 0.0
    if prev in STANCE and word in FOLLOWERS:
        return None, 0.5
    return None, 0.0

programs.luna:
"""Cue the component on words expressing thought, belief, perception or stance.

Its strongest observed bursts center on words such as “think,” “believe,”
“hope” and “like.” Perception verbs and epistemic judgments are weaker cues;
for “like,” require a nearby feel/seem/sound/look construction. This simple
lexical sketch captures recurring responses, not all contextual variation.
"""
READS = ()

THOUGHT = {
    "think": 2.0, "thinks": 2.0, "thought": 2.0, "thinking": 1.0,
    "know": 1.4, "knows": 1.2, "knew": 1.2,
    "remember": 1.1, "recall": 0.8, "believe": 1.8,
    "believes": 1.3, "trust": 1.8, "hope": 1.8, "suspect": 1.8,
    "guess": 1.4, "guessing": 1.8, "wonder": 0.9,
    "suppose": 0.9, "assume": 0.8, "imagine": 0.9,
    "consider": 0.8, "realize": 0.9, "understand": 0.8,
    "notice": 1.0, "perceive": 0.7, "disagree": 1.0,
    "agree": 0.7, "doubt": 0.8, "expect": 0.8,
}
PERCEPTION = frozenset({
    "feel", "feels", "felt", "seem", "seems", "seemed",
    "sound", "sounds", "sounded", "look", "looks", "looked",
})
JUDGMENT = {
    "sure": 0.9, "unsure": 1.2, "certain": 0.7,
    "uncertain": 0.7, "unlikely": 0.8, "likely": 0.6,
    "thrilled": 0.8,
}


def clean(token):
    return token.strip().lower().strip(".,!?;:()[]{}\"'")


def step(carry, prefix, upstream):
    word = clean(prefix.token_strings[-1])
    if word in THOUGHT:
        return None, THOUGHT[word]
    if word in JUDGMENT:
        return None, JUDGMENT[word]
    if word in PERCEPTION:
        return None, 0.8
    if word in {"want", "need", "wish", "prefer"}:
        return None, 0.5
    if word == "like" and len(prefix.token_strings) > 1:
        same_doc = prefix.document_ids[-2] == prefix.document_ids[-1]
        if same_doc and clean(prefix.token_strings[-2]) in PERCEPTION:
            return None, 1.8
    return None, 0.0

programs.sol:
"""Approximate a lexical response to 'how', not a general question parser.

English 'how' gets a large negative value, modulated by capitalization,
attached punctuation, document position, and a few preceding word classes.
Other question words and 'however' get smaller responses. Non-English forms
are grouped by approximate strength rather than fitted separately.
Unrecognized tokens get zero. State resets at each document boundary.
"""
import math
import string

READS = ()
# Lowercase and capitalized forms, respectively.
ENGLISH = {
    'what': (-0.54, -0.98), 'when': (-0.79, -0.85),
    'why': (-0.61, -0.90), 'whether': (-0.65, -1.00),
    'however': (-1.16, -0.97), 'where': (0.04, -0.26),
    'who': (0.15, -0.07), 'which': (0.03, -0.17),
}
QUESTION_AUXILIARIES = {'Can': -0.47, 'Are': -0.28, 'Is': -0.18,
                        'Do': -0.11, 'Does': -0.29}
MANNER_FORMS = frozenset(
    'wie hoe jak Jak Hoe nasıl cómo Cómo 如何 どう hvor'.split())
STRONG_MANNER_FORMS = frozenset(
    'Wie Как hvordan Nasıl どのように 어떻게 كيف كيفية'.split())
WEAKER_QUESTION_FORMS = frozenset('como Como как 怎么 怎 いか なぜ 何'.split())
EXPLAINING = {'explain', 'explains', 'explained', 'explaining',
              'specify', 'specifies', 'specified', 'specifying'}
UNDERSTANDING = {'understand', 'understands', 'understood', 'understanding'}
SHOWING = {'show', 'shows', 'showed', 'showing', 'see', 'sees', 'seeing'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    position = 0 if new_document else carry[1] + 1
    previous = '' if new_document else carry[2]
    token = prefix.token_strings[-1]
    spelling = token.strip()
    word = spelling.lstrip(string.punctuation + '“‘')
    spaced = token[:1].isspace()
    lower = word.lower()
    if lower == 'how':
        if spelling.startswith('/'):
            base, boost = -8.4, 0.0
        elif spelling.startswith('-'):
            base, boost = -5.0, 0.0
        elif spelling.startswith(('.', '"', '“')):
            base, boost = -6.2, 0.0
        elif word == 'How':
            base, boost = (-7.1, 3.6) if spaced else (-7.1, 6.8)
        elif word == 'HOW':
            base, boost = (-7.6 if spaced else -5.8), 0.0
        else:
            base, boost = (-6.83, 0.4) if spaced else (-6.5, 0.0)
        value = base - boost / math.sqrt(position + 1)
        if previous == 'matter':
            value += 2.9
        elif previous in EXPLAINING:
            value += 1.3
        elif previous in UNDERSTANDING:
            value += 1.0
        elif previous in SHOWING:
            value += 0.5
        elif previous == 'any' and not spaced:
            value += 3.8
        elif previous in {'and', ','}:
            value -= 0.6
        elif previous and not previous.strip('#'):
            value -= 0.7
        elif previous.endswith('?'):
            value += 0.8
    elif lower in ENGLISH:
        capital = word[0].isupper()
        value = ENGLISH[lower][int(capital)]
        if not spaced and (capital or lower in {
                'what', 'when', 'why', 'whether', 'who', 'however'}):
            value -= 0.18
    elif word in QUESTION_AUXILIARIES:
        value = QUESTION_AUXILIARIES[word] - (0.18 if not spaced else 0.0)
    elif word in MANNER_FORMS:
        value = -0.8 if not spaced and word in {'wie', 'hoe', 'jak'} else -2.0
    elif word in STRONG_MANNER_FORMS:
        value = -2.7
    elif word in WEAKER_QUESTION_FORMS:
        value = -1.0
    else:
        value = -0.5 if spelling == '¿' else 0.0
    return (doc, position, spelling.lower()), float(value)

programs.haiku:
"""Layer-0 MLP output feature (down_proj component 894): a "how" question-word detector.

The component writes a strongly negative value onto the residual stream at the word
"how", whatever its capitalisation or spacing: about -7. The word "how" in other
languages (wie, jak, как, cómo, hoe, 如何, 怎么, どう, nasıl, 어떻게) is about -1.7.
Other question words (when, what, why, however, whether, почему, когда, hur, quanto)
are weakly negative, about -0.8. Every other token is about 0: the component is silent
on ordinary text, and on the words for "where", "who", "which", "if", "can".
"""

READS = ()

HOW_ENGLISH = {"how"}
HOW_OTHER_LANGUAGES = {
    "wie", "jak", "как", "cómo", "hoe", "如何", "怎么", "怎", "どう", "nasıl", "어떻게",
}
WEAK_QUESTION_WORDS = {
    "when", "what", "why", "however", "whether", "почему", "когда", "hur", "quanto",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(" /-.\n\t").lower()
    if word in HOW_ENGLISH:
        value = -7.0
    elif word in HOW_OTHER_LANGUAGES:
        value = -1.7
    elif word in WEAK_QUESTION_WORDS:
        value = -0.8
    else:
        value = 0.0
    return carry, value
